def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    if h <= 2 or w <= 2:
        return [row[:] for row in grid]

    # The input is a lattice of identical-sized cells separated by one-cell
    # grid lines.  The output keeps all vertical cells but collapses all
    # horizontal cells into a single horizontal cell per row-block.
    #
    # Find the interior size m:
    #   border lines are repeated every m+1 rows/cols.
    # The first row/col is border.  The first interior row/col starts at 1.
    #
    # Detect m by finding the first repeated full border line after row 0.

    def row_key(r):
        return tuple(grid[r])

    border_row0 = row_key(0)

    m = None
    for period in range(1, h):
        if row_key(period) == border_row0:
            # Check that this period can tile the height.
            if (h - 1) % period == 0:
                m = period - 1
                break
    if m is None:
        return [row[:] for row in grid]

    # Number of vertical cells.
    v_cells = (h - 1) // (m + 1)

    # Detect horizontal interior size similarly from first row.
    def col_key(c):
        return tuple(grid[r][c] for r in range(h))

    border_col0 = col_key(0)
    m_h = None
    for period in range(1, w):
        if col_key(period) == border_col0 and (w - 1) % period == 0:
            m_h = period - 1
            break
    # The task structure has square cells; but use the detected horizontal m
    # if it differs.
    if m_h is None:
        m_h = m
    h_cells = (w - 1) // (m_h + 1)

    # Border colour is colour of grid lines.
    border = grid[0][0]

    # Build output grid: same height, width = interior + 2 border columns.
    out_w = m_h + 2
    out = [[border] * out_w for _ in range(h)]

    # Fill vertical border lines.
    for r in range(0, h, m_h + 1):
        for c in range(out_w):
            out[r][c] = border

    # For each vertical cell row, choose which horizontal cell to output.
    #
    # Empirically, each row-block contains one "odd" cell.  We choose it by:
    # 1. If exactly one horizontal cell has the minimum Hamming distance to
    #    the majority/canonical cell, pick it.
    # 2. If exactly one cell is a unique whole-cell pattern, pick it.
    # 3. Fallback: pick the cell with the maximum number of border-colour
    #    intrusions or, failing that, the rightmost distinct cell.
    #
    # To be robust, compare the actual interior cells as tuples.

    def cell(v, j):
        r0 = v * (m_h + 1) + 1
        c0 = j * (m_h + 1) + 1
        return tuple(
            tuple(grid[r0 + dr][c0 + dc] for dc in range(m_h))
            for dr in range(m_h)
        )

    def flat(cell_tuple):
        return tuple(x for row in cell_tuple for x in row)

    def count_distinct(cells):
        # count occurrences of each flat cell
        counts = {}
        for t in cells:
            f = flat(t)
            counts[f] = counts.get(f, 0) + 1
        return counts

    for v in range(v_cells):
        cells = [cell(v, j) for j in range(h_cells)]
        flats = [flat(c) for c in cells]
        counts = {}
        for f in flats:
            counts[f] = counts.get(f, 0) + 1

        # Unique whole cell?
        unique = [idx for idx, f in enumerate(flats) if counts[f] == 1]
        if len(unique) == 1:
            chosen = unique[0]
        else:
            # Pick the cell that is most different from the most common cell.
            common = max(counts.items(), key=lambda kv: kv[1])[0]
            best = None
            best_score = -1
            for idx, f in enumerate(flats):
                if f == common:
                    continue
                score = sum(1 for a, b in zip(f, common) if a != b)
                if score > best_score:
                    best_score = score
                    best = idx
            if best is None:
                chosen = 0
            else:
                chosen = best

        # Copy chosen cell into output.
        r0 = v * (m_h + 1) + 1
        for dr in range(m_h):
            for dc in range(m_h):
                out[r0 + dr][1 + dc] = grid[r0 + dr][chosen * (m_h + 1) + 1 + dc]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Keep all non-1 cells unchanged.
    out = [[cell for cell in row] for row in grid]

    # Rebuild only the 1-cells.
    for r in range(R):
        for c in range(C):
            out[r][c] = 0 if out[r][c] == 1 else out[r][c]

    # A zero cell becomes 1 iff:
    # 1) it is horizontally between two equal non-1, non-zero colors in its row, or
    # 2) it is vertically between two equal non-1, non-zero colors in its column.
    for r in range(R):
        row = out[r]
        c = 0
        while c < C:
            # Find the next non-1 obstacle/background segment start.
            if row[c] not in (0, 1):
                color = row[c]
                c += 1
                # If the next non-1 cell in the same row has the same color,
                # fill all cells between them.
                nxt = c
                while nxt < C and row[nxt] == 0:
                    nxt += 1
                if nxt < C and row[nxt] == color:
                    for cc in range(c, nxt):
                        out[r][cc] = 1
                c = nxt + 1
            else:
                c += 1

    for c in range(C):
        r = 0
        while r < R:
            if out[r][c] not in (0, 1):
                color = out[r][c]
                r += 1
                nxt = r
                while nxt < R and out[nxt][c] == 0:
                    nxt += 1
                if nxt < R and out[nxt][c] == color:
                    for rr in range(r, nxt):
                        out[rr][c] = 1
                r = nxt + 1
            else:
                r += 1

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background is the most common cell colour.
    vals, counts = np.unique(a, return_counts=True
    bg = int(vals[np.argmax(counts)])

    # Marker colour is the colour of the smallest non-background object.
    # In the given tasks this is the small colour-4 object.
    marker_color = None
    min_size = None

    # Connected components (8-connected) for non-background cells.
    seen = np.zeros((h, w), dtype=bool)
    for i in range(h):
        for j in range(w):
            if seen[i, j] or a[i, j] == bg:
                continue
            color = int(a[i, j])
            stack = [(i, j)]
            comp = []
            seen[i, j] = True
            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and a[nr, nc] == color:
                            seen[nr, nc] = True
                            stack.append((nr, nc))
            if min_size is None or len(comp) < min_size:
                min_size = len(comp)
                marker_color = color

    # Marker column interval: the bounding box of the smallest component.
    if marker_color is None:
        return [[int(x) for x in row] for row in a]

    marker_cells = [(i, j) for i in range(h) for j in range(w) if a[i, j] == marker_color]
    cols = [j for _, j in marker_cells]
    c_min, c_max = min(cols), max(cols)

    # Object colour: the non-background colour other than the marker.
    # If there are several, use the most frequent one.
    obj_counts = {}
    for val, cnt in zip(vals, counts):
        val = int(val)
        if val != bg and val != marker_color:
            obj_counts[val] = int(cnt)
    if not obj_counts:
        obj = None
    else:
        obj = max(obj_counts, key=lambda x: obj_counts[x])

    out = a.copy()

    # Fixed vertical rhythm:
    # row % 6 == 0 -> colour 3
    # row % 6 in {2, 4} -> colour 4
    # otherwise the row is inactive.
    for r in range(h):
        m = r % 6
        if m == 0:
            # Paint colour 3 on all horizontal runs of the main object colour,
            # and also on the marker column interval.
            c = 0
            while c < w:
                if a[r, c] == obj:
                    s = c
                    while c < w and a[r, c] == obj:
                        c += 1
                    e = c - 1
                    # Extend by one cell on each side if still inside the grid
                    # and the neighbour is background.
                    if s > 0 and a[r, s - 1] == bg:
                        s -= 1
                    if e + 1 < w and a[r, e + 1] == bg:
                        e += 1
                    out[r, s:e + 1] = 3
                else:
                    c += 1

            # Always stamp the marker interval.
            out[r, c_min:c_max + 1] = 3

        elif m in (2, 4):
            # Paint colour 4 on all horizontal runs of the main object colour,
            # clipped to length 4, and always stamp the marker interval.
            c = 0
            while c < w:
                if a[r, c] == obj:
                    s = c
                    while c < w and a[r, c] == obj:
                        c += 1
                    e = c - 1
                    # Clip the run to at most 4 cells, taking its left part.
                    if e - s + 1 > 4:
                        e = s + 3
                    out[r, s:e + 1] = 4
                else:
                    c += 1

            out[r, c_min:c_max + 1] = 4

    return [[int(x) for x in row] for row in out]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    if g.size == 0:
        return []
    h, w = g.shape

    # Background = most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components (8-connected) of non-background cells.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for i in range(h):
        for j in range(w):
            if seen[i, j] or g[i, j] == bg:
                continue
            color = int(g[i, j])
            q = deque([(i, j)])
            seen[i, j] = True
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] == color:
                            seen[nr, nc] = True
                            q.append((nr, nc))
            comps.append((color, cells))

    # Marker component = smallest non-background component.
    # Object colour = most frequent colour among the other components.
    marker_color = None
    marker_comp = None
    min_size = None
    for color, cells in comps:
        if min_size is None or len(cells) < min_size:
            min_size = len(cells)
            marker_color = color
            marker_comp = cells

    if marker_comp is None:
        return [[int(x) for x in row] for row in g]

    mc_min = min(c[1] for c in marker_comp)
    mc_max = max(c[1] for c in marker_comp)

    other_counts = {}
    for color, cells in comps:
        if color != marker_color:
            other_counts[color] = other_counts.get(color, 0) + len(cells)

    obj_color = None
    if other_counts:
        obj_color = max(other_counts, key=lambda x: other_counts[x])

    out = g.copy()

    for r in range(h):
        if r % 2 == 1:
            continue

        stamp = 3 if r % 6 == 0 else 4

        if stamp == 3 and obj_color is not None:
            # Paint every maximal horizontal run of the main object colour.
            c = 0
            while c < w:
                if g[r, c] == obj_color:
                    start = c
                    while c < w and g[r, c] == obj_color:
                        c += 1
                    out[r, start:c] = 3
                else:
                    c += 1

        # Always stamp the marker column interval.
        out[r, mc_min:mc_max + 1] = stamp

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Work on a copy.
    out = [list(row) for row in grid]

    # 1) Replace every horizontal run of three 7s by 868.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 7 and c + 2 < w and grid[r][c + 1] == 7 and grid[r][c + 2] == 7:
                out[r][c] = 8
                out[r][c + 1] = 6
                out[r][c + 2] = 8
                c += 3
            else:
                c += 1

    # 2) Put a vertical 6 through the centre of every such triple,
    #    one cell above and one cell below the triple when possible.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 7 and c + 2 < w and grid[r][c + 1] == 7 and grid[r][c + 2] == 7:
                mid = c + 1
                if r - 1 >= 0:
                    out[r - 1][mid] = 6
                if r + 1 < h:
                    out[r + 1][mid] = 6
                c += 3
            else:
                c += 1

    # 3) Colouring for non-7 / non-6 cells:
    #    - 0 stays 0.
    #    - A cell becomes 3 if it is on the outside left/right edge and
    #      touches a 0 horizontally, or if it has a 0 to the left or right.
    #    - Otherwise old 3 and 8 cells become 8.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                continue
            if out[r][c] == 6:
                continue

            left_zero = c > 0 and out[r][c - 1] == 0
            right_zero = c + 1 < w and out[r][c + 1] == 0

            if (c == 0 or c == w - 1) and (left_zero or right_zero):
                out[r][c] = 3
            elif left_zero or right_zero:
                out[r][c] = 3
            else:
                out[r][c] = 8

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Start from the input.  Zeros are never changed.
    out = [list(row) for row in grid]

    # 1) Replace every horizontal run of three 7s by 868, and add a 6
    #    immediately above and below the centre of the run when possible.
    for r in range(h):
        c = 0
        while c < w:
            if (
                c + 2 < w
                and grid[r][c] == 7
                and grid[r][c + 1] == 7
                and grid[r][c + 2] == 7
            ):
                mid = c + 1
                out[r][c] = 8
                out[r][mid] = 6
                out[r][c + 2] = 8
                if r - 1 >= 0:
                    out[r - 1][mid] = 6
                if r + 1 < h:
                    out[r + 1][mid] = 6
                c += 3
            else:
                c += 1

    # 2) Recompute the remaining 3 / 8 background.
    #    0 stays 0, and the newly placed 6s stay 6.
    #    A non-zero / non-six cell becomes 3 iff it has at least one
    #    orthogonal neighbour whose input value is 3.  Otherwise it is 8.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0 or out[r][c] == 6:
                continue

            has_input_3 = False
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3:
                    has_input_3 = True
                    break

            out[r][c] = 3 if has_input_3 else 8

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0])

    # locate the two vertical walls
    left_wall = -1
    right_wall = -1
    for c in range(w):
        col = {grid[r][c] for r in range(h) if grid[r][c] != 0}
        if len(col) == 1 and 0 not in col:
            if left_wall == -1:
                left_wall = c
            else:
                right_wall = c
                break

    top_wall = 0
    bottom_wall = h - 1

    inner = left_wall + 1

    # collect source shapes strictly left of the left wall
    sources = {}
    for r in range(top_wall + 1, bottom_wall):
        for c in range(0, left_wall):
            color = grid[r][c]
            if color == 0:
                continue
            if color not in sources:
                # find 8-connected component
                cells = []
                stack = [(r, c)]
                seen = {(r, c)}
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if (
                                0 <= ny < h and
                                0 <= nx < left_wall and
                                (ny, nx) not in seen and
                                grid[ny][nx] == color
                            ):
                                seen.add((ny, nx))
                                stack.append((ny, nx))
                sources[color] = cells
            elif (r, c) not in set(sources[color]):
                # safety: if multiple components of same colour, keep first
                pass

    # place each source shape at every matching marker intersection
    # marker rows from the inner-left wall, marker cols from the top wall
    for color, cells in sources.items():
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)
        rh = max_r - min_r + 1
        rw = max_c - min_c + 1
        offset_r = (rh - 1) // 2
        offset_c = (rw - 1) // 2

        rows_marked = []
        for r in range(top_wall + 1, bottom_wall):
            if grid[r][inner] == color:
                rows_marked.append(r)

        cols_marked = []
        for c in range(left_wall + 1, right_wall):
            if grid[top_wall][c] == color:
                cols_marked.append(c)

        for rr in rows_marked:
            for cc in cols_marked:
                # translate source so its centre goes to (rr, cc)
                base_r = rr - offset_r
                base_c = cc - offset_c
                for y, x in cells:
                    ny = base_r + (y - min_r)
                    nx = base_c + (x - min_c)
                    if 0 <= ny < h and 0 <= nx < w:
                        out[ny][nx] = color

    # clear source shapes on the left
    for color, cells in sources.items():
        for y, x in cells:
            out[y][x] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros_like(g)

    def label(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < H and 0 <= nx < W:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        q.append((ny, nx))
                    comps.append(cells)
        return comps

    def bbox(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return min(ys), max(ys), min(xs), max(xs)

    # Largest non-background object is the static frame.
    all_comps = label(g != 0)
    if not all_comps:
        return [list(map(int, row)) for row in grid]

    frame_cells = max(all_comps, key=len)
    frame_color = g[frame_cells[0][0], frame_cells[0][1]]
    for y, x in frame_cells:
        out[y, x] = frame_color

    # Small objects.
    small_cells = [c for c in all_comps if c is not frame_cells]
    objs = []
    for cells in small_cells:
        y1, y2, x1, x2 = bbox(cells)
        objs.append({
            "cells": cells,
            "color": g[cells[0][0], cells[0][1]],
            "bbox": (y1, y2, x1, x2),
            "size": len(cells),
            "y1": y1,
            "x1": x1,
            "cx": (x1 + x2) / 2,
            "cy": (y1 + y2) / 2,
        })

    if not objs:
        return [list(map(int, row)) for row in out]

    # Empty spaces adjacent to the frame inside the frame's bounding box.
    fy1, fy2, fx1, fx2 = bbox(frame_cells)
    frame_set = set(frame_cells)
    holes = []
    for y in range(fy1, fy2 + 1):
        for x in range(fx1, fx2 + 1):
            if g[y, x] != 0:
                continue
            ok = False
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if (y + dy, x + dx) in frame_set:
                        ok = True
                        break
                if ok:
                    break
            if ok:
                holes.append((y, x))

    if not holes:
        return [list(map(int, row)) for row in out]

    # For each object, choose the frame hole nearest to its current center.
    objs.sort(key=lambda o: (o["size"], o["cy"], o["cx"]))
    assignments = {}
    for o in objs:
        best = None
        bd = None
        for hy, hx in holes:
            d = (hy - o["cy"]) ** 2 + (hx - o["cx"]) ** 2
            if bd is None or d < bd:
                bd = d
                best = (hy, hx)
        assignments[o] = best

    # Draw objects.  Larger objects are drawn first; the frame and previously
    # drawn smaller objects act as masks, producing the observed interlocking.
    for o in objs:
        y1, y2, x1, x2 = o["bbox"]
        oy1, ox1 = assignments[o]

        # Try all 8 rotations/reflections and choose the orientation that
        # causes the fewest overlaps with already non-zero output cells.
        best_rot = None
        best_cost = 10**9

        for k in range(4):
            for flip in (False, True):
                pts = o["cells"]
                if flip:
                    pts = [(y, -x) for y, x in pts]
                # Normalize.
                miny = min(y for y, _ in pts)
                minx = min(x for _, x in pts)
                norm = [(y - miny, x - minx) for y, x in pts]
                if k % 2 == 1:
                    norm = [(x, -y) for y, x in norm]
                    miny = min(y for y, _ in norm)
                    minx = min(x for _, x in norm)
                    norm = [(y - miny, x - minx) for y, x in norm]

                ry1 = min(y for y, _ in norm)
                rx1 = min(x for _, x in norm)
                ry2 = max(y for y, _ in norm)
                rx2 = max(x for _, x in norm)
                # Place the normalized bounding box so its top-left is at the
                # same relative offset as the original bbox top-left to hole.
                ny1 = oy1 - y1
                nx1 = ox1 - x1
                target = [(ny1 + (y - ry1), nx1 + (x - rx1)) for y, x in norm]

                cost = 0
                valid = True
                for ty, tx in target:
                    if not (0 <= ty < H and 0 <= tx < W):
                        valid = False
                        break
                    if out[ty, tx] != 0:
                        cost += 1
                if not valid:
                    continue
                if cost < best_cost:
                    best_cost = cost
                    best_rot = target

        if best_rot is None:
            # Fallback: unrotated placement.
            best_rot = [(assignments[o][0] - y1 + (y - y1),
                         assignments[o][1] - x1 + (x - x1))
                        for y, x in o["cells"]]

        color = o["color"]
        for ty, tx in best_rot:
            if 0 <= ty < H and 0 <= tx < W and out[ty, tx] == 0:
                out[ty, tx] = color

        # If some cells were blocked, leave them empty; this matches the
        # clipping/interlocking seen in the examples.

    return [list(map(int, row)) for row in out]

