import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    best = None

    # Try all possible frame top-left corners and frame sizes.
    # The frame is a rectangle with a 1-cell border of a single color.
    for r in range(h - 3):
        for c in range(w - 3):
            for size in range(3, min(h, w) - r - c + 1):
                r1, c1 = r + size, c + size
                if r1 > h or c1 > w:
                    continue

                border = g[r, c]
                if border == 0:
                    continue

                # Check that the full 1-cell border has the same color.
                ok = True
                for x in range(c, c1):
                    if g[r, x] != border or g[r1 - 1, x] != border:
                        ok = False
                        break
                if not ok:
                    continue
                for y in range(r, r1):
                    if g[y, c] != border or g[y, c1 - 1] != border:
                        ok = False
                        break
                if not ok:
                    continue

                # Interior of the frame.
                inner = g[r + 1:r1 - 1, c + 1:c1 - 1]
                if inner.size == 0:
                    continue

                vals, counts = np.unique(inner, return_counts=True)
                if len(vals) != 2:
                    continue

                # The encoded interior must contain zero and exactly one other color.
                if 0 not in vals:
                    continue

                nonzero = int([v for v in vals if v != 0][0])
                if nonzero == border:
                    continue

                score = int(counts[[int(v) for v in vals].index(nonzero)][0])
                # Prefer larger interiors and more frequent encoded foreground color.
                key = (score, inner.size)
                if best is None or key > best[0]:
                    best = (key, inner.copy(), nonzero)

    if best is None:
        # Fallback: should not happen for valid puzzle inputs.
        return []

    _, inner, fg = best

    out = np.zeros(inner.shape, dtype=int)
    out[inner == 0] = fg
    out[inner == fg] = 0

    return out.tolist()

