def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [list(row) for row in grid]
    H = len(grid)
    W = len(grid[0])

    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    if not cnt:
        return grid
    bg = cnt.most_common(1)[0][0]

    out = [row[:] for row in grid]

    # marker: most common non-background colour
    marker = None
    for c, n in cnt.items():
        if c == bg:
            continue
        if marker is None or n > cnt[marker]:
            marker = c

    # reference marker: an isolated marker cell (not 8-connected to any other marker)
    ref_r = ref_c = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == marker:
                isolated = True
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < H and 0 <= cc < W and grid[rr][cc] == marker:
                            isolated = False
                            break
                    if not isolated:
                        break
                if isolated:
                    ref_r, ref_c = r, c
                    break
        if ref_r is not None:
            break

    # axis:
    # - if reference is isolated and horizontal distance from grid centre >= vertical distance: horizontal
    # - otherwise vertical
    axis = "h"
    if ref_r is not None:
        if abs(ref_c - (W - 1) / 2.0) >= abs(ref_r - (H - 1) / 2.0):
            axis = "h"
        else:
            axis = "v"

    # target coordinate
    if axis == "h":
        target = ref_c
        if ref_c == (W - 1) / 2.0:
            target = int(round(W / 2))
        else:
            center = (W - 1) / 2.0
            # move away from the centre by one step
            target = ref_c + (1 if ref_c > center else -1)
    else:
        target = ref_r
        if ref_r == (H - 1) / 2.0:
            target = int(round(H / 2))
        else:
            center = (H - 1) / 2.0
            target = ref_r + (1 if ref_r > center else -1)

    # connected components using all non-background cells
    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and not visited[r][c]:
                stack = [(r, c)]
                comp = []
                visited[r][c] = True
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not visited[ny][nx] and grid[ny][nx] != bg:
                                    visited[ny][nx] = True
                                    stack.append((ny, nx))
                components.append(comp)

    # erase all non-background cells
    for r in range(H):
        for c in range(W):
            if out[r][c] != bg:
                out[r][c] = bg

    # place each component with its marker cell aligned to target
    for comp in components:
        marker_cells = [(r, c) for (r, c) in comp if grid[r][c] == marker]
        if not marker_cells:
            continue

        # If the component is a single marker cell and it is the reference, keep it fixed.
        if len(marker_cells) == 1 and len(comp) == 1:
            if ref_r is not None and (marker_cells[0][0], marker_cells[0][1]) == (ref_r, ref_c):
                continue

        # For components with several marker cells, take the median marker position.
        if axis == "h":
            xs = sorted(c for _, c in marker_cells)
            m = xs[len(xs) // 2]
        else:
            ys = sorted(r for r, _ in marker_cells)
            m = ys[len(ys) // 2]

        if axis == "h":
            shift = target - m
            if shift == 0:
                continue
        else:
            shift = target - m
            if shift == 0:
                continue

        for (r, c) in comp:
            nr, nc = (r + shift, c) if axis == "h" else (r, c + shift)
            if 0 <= nr < H and 0 <= nc < W:
                out[nr][nc] = grid[r][c]

    return out

