from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Background colour: most frequent overall.
    all_counts = Counter(v for row in grid for v in row)
    bg = all_counts.most_common(1)[0][0]

    def is_isolated_nonbg(r, c):
        if grid[r][c] == bg:
            return False
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < H and 0 <= cc < W and grid[rr][cc] != bg:
                    return False
        return True

    # Find isolated non-background cells and their colours.
    isolated_by_color = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != bg and is_isolated_nonbg(r, c):
                isolated_by_color.setdefault(v, []).append((r, c))

    # Marker colours: colours that have an isolated reference and also occur elsewhere.
    marker_colors = []
    for color, refs in isolated_by_color.items():
        if all_counts[color] > len(refs):
            marker_colors.append(color)

    # Connected components of all non-background cells.
    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not visited[ny][nx] and grid[ny][nx] != bg:
                                    visited[ny][nx] = True
                                    stack.append((ny, nx))
                components.append(comp)

    # Output starts as background.
    out = [[bg] * W for _ in range(H)]

    # Determine reference axis/target for each marker colour.
    # A reference cell chooses the border it is closest to.
    # left/right => align rows; top/bottom => align columns.
    ref_info = {}
    for color in marker_colors:
        refs = isolated_by_color[color]
        # If there are several isolated references, choose the one whose border is closest.
        def border_priority(ref):
            r, c = ref
            d_top = r
            d_bottom = H - 1 - r
            d_left = c
            d_right = W - 1 - c
            min_d = min(d_top, d_bottom, d_left, d_right)
            # left/right priority first for ties
            if min(d_left, d_right) == min_d:
                return (0, min_d, -1 if d_left <= d_right else 1, 0)
            else:
                return (1, min_d, 0, -1 if d_top <= d_bottom else 1)

        best_ref = min(refs, key=border_priority)
        r, c = best_ref
        d_top = r
        d_bottom = H - 1 - r
        d_left = c
        d_right = W - 1 - c

        if min(d_left, d_right) <= min(d_top, d_bottom):
            ref_info[color] = ("row", r)
        else:
            ref_info[color] = ("col", c)

    # Apply all movements.
    for comp in components:
        shifts = {}  # color -> (dy, dx)
        for color in marker_colors:
            if color not in ref_info:
                continue
            axis, target = ref_info[color]
            cells = [(r, c) for (r, c) in comp if grid[r][c] == color]
            if not cells:
                continue

            if axis == "row":
                vals = sorted(r for r, _ in cells)
                med = vals[len(vals) // 2]
                dy = target - med
                dx = 0
            else:
                vals = sorted(c for _, c in cells)
                med = vals[len(vals) // 2]
                dy = 0
                dx = target - med

            if dy == 0 and dx == 0:
                continue
            shifts[color] = (dy, dx)

        # For a component containing multiple marker colours, use the non-zero shift
        # if exactly one marker colour requires movement; otherwise no movement.
        if len(shifts) == 1:
            dy, dx = next(iter(shifts.values()))
            for r, c in comp:
                nr, nc = r + dy, c + dx
                if 0 <= nr < H and 0 <= nc < W:
                    out[nr][nc] = grid[r][c]
        elif not shifts:
            # No marker: leave unchanged.
            for r, c in comp:
                out[r][c] = grid[r][c]

    # Isolated reference cells are already placed unchanged in the “no movement” case above.
    return out

