def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    sevens = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 7]

    out = [[1] * w for _ in range(h)]
    if not twos:
        return out

    if len(twos) == 2:
        (r1, c1), (r2, c2) = twos

        if r1 == r2:
            lo, hi = (c1, c2) if c1 < c2 else (c2, c1)
            for c in range(lo, hi + 1):
                out[r1][c] = 2
        elif c1 == c2:
            lo, hi = (r1, r2) if r1 < r2 else (r2, r1)
            for r in range(lo, hi + 1):
                out[r][c1] = 2
        else:
            corner_r, corner_c = r1, c2
            for r in range(min(r1, r2), max(r1, r2) + 1):
                out[r][corner_c] = 2
            for c in range(min(c1, c2), max(c1, c2) + 1):
                out[corner_r][c] = 2

        if sevens:
            min_r = min(r for r, _ in sevens)
            max_r = max(r for r, _ in sevens)
            min_c = min(c for _, c in sevens)
            max_c = max(c for _, c in sevens)
            dh = max_r - min_r + 1
            dw = max_c - min_c + 1

            top = r2 if r2 < r1 else r1
            bottom = r1 if r2 < r1 else r2
            left = c1 if c1 < c2 else c2
            right = c2 if c1 < c2 else c1

            for dr in range(dh):
                for dc in range(dw):
                    if grid[min_r + dr][min_c + dc] == 7:
                        out[bottom - 1 - dr][left - 1 - dc] = 7
                        if top > 0:
                            out[dr][w - dc - 1] = 7
    else:
        r2, c2 = twos[0]
        if sevens:
            in_col = [r for r in range(h) if grid[r][c2] == 7]
            if in_col:
                near = min(in_col, key=lambda r: abs(r - r2))
                above = near < r2
                for dr in range(1, h):
                    if above:
                        rr = near - dr
                    else:
                        rr = near + dr
                    if 0 <= rr < h:
                        out[rr][c2] = 2
                for rr in in_col:
                    out[rr][c2] = 7
            min_r = min(r for r, _ in sevens)
            max_r = max(r for r, _ in sevens)
            min_c = min(c for _, c in sevens)
            max_c = max(c for _, c in sevens)
            dh = max_r - min_r + 1
            dw = max_c - min_c + 1
            left = c2 < min_c
            if left:
                off = min_c - c2
            else:
                off = max_c - c2 + 1
            for dr in range(dh):
                for dc in range(dw):
                    if grid[min_r + dr][min_c + dc] == 7:
                        rr = h - dh + dr
                        if left:
                            cc = dc - off
                        else:
                            cc = w - dw + dc - off
                        if 0 <= cc < w:
                            out[rr][cc] = 7

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [list(row) for row in grid]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Connected components of colour 1 (8-connected)
    comp_id = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and comp_id[r][c] == -1:
                cid = len(comps)
                cells = []
                q = deque([(r, c)])
                comp_id[r][c] = cid
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and comp_id[ny][nx] == -1 and grid[ny][nx] == 1:
                                comp_id[ny][nx] = cid
                                q.append((ny, nx))
                cells.sort(reverse=True)  # top-left first
                comps.append((cid, cells))

    # For each 1-component, find a straight tail attached to it.
    def component_bounding(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return min(ys), min(xs), max(ys), max(xs)

    # Directions: (dr, dc, name)
    dirs = [(-1, 0, 'U'), (0, 1, 'R'), (1, 0, 'D'), (0, -1, 'L')]

    def extend_run(line, period, max_len=None):
        # line: list of colour tuples, ordered from anchor outward.
        # Extend by repeating the shortest period inferred from the observed line.
        if not line:
            return
        # Determine shortest period p <= len(line), preferring small p.
        n = len(line)
        p = 1
        while p <= n:
            ok = True
            for i in range(p, n):
                if line[i] != line[i - p]:
                    ok = False
                    break
            if ok:
                break
            p += 1
        # Build extended sequence up to max_len slices
        if max_len is None or max_len <= n:
            return
        for i in range(n, max_len):
            out_line = line[i % p]
            yield out_line

    def add_slice(direction, start_r, start_c, colors, existing_len, max_len):
        """
        Write slices of the tail into out.
        start_r/c: first existing slice adjacent to component.
        colors: list of tuples, first slice at distance 0 (existing first slice).
        existing_len: number of existing slices in direction.
        max_len: maximum possible slices before edge.
        Only writes slices beyond existing_len (and never overwrites existing non-8
        except where an extension crosses another line: later components overwrite).
        """
        dr, dc = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}[direction]
        # Write from farthest back to nearest? To allow later components to overwrite
        # earlier ones at intersections, components are processed top-left first and we
        # write near-to-far; simple.
        if max_len <= existing_len:
            return
        # Build full pattern using existing slices.
        period = 1
        while period <= existing_len:
            ok = True
            for i in range(period, existing_len):
                if colors[i] != colors[i - period]:
                    ok = False
                    break
            if ok:
                break
            period += 1
        for dist in range(existing_len, max_len):
            slice_colors = colors[dist % period]
            r = start_r + dr * dist
            c = start_c + dc * dist
            if direction in ('U', 'D'):
                # slice is horizontal tuple
                for k, col in enumerate(slice_colors):
                    rr, cc = r, c + k
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = col
            else:
                # slice is vertical tuple
                for k, col in enumerate(slice_colors):
                    rr, cc = r + k, c
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = col

    processed = set()
    for cid, cells in comps:
        y0, x0, y1, x1 = component_bounding(cells)

        # Collect candidate tails.
        # A tail is a maximal straight run of non-1/non-8 cells immediately adjacent
        # to the component side.
        for dr, dc, name in dirs:
            # Start line adjacent to component side.
            if name == 'U':
                base_r = y0 - 1
                base_cs = [c for c in range(x0, x1 + 1) if base_r >= 0 and grid[base_r][c] != 8 and grid[base_r][c] != 1]
                if not base_cs:
                    continue
                # Consecutive columns only
                if len(base_cs) > 1:
                    if any(base_cs[i+1] - base_cs[i] != 1 for i in range(len(base_cs)-1)):
                        continue
                c_start = base_cs[0]
                c_width = len(base_cs)
                # Measure run upward
                run = []
                r = base_r
                while r >= 0:
                    row_vals = tuple(grid[r][c_start + k] for k in range(c_width))
                    if any(v == 8 or v == 1 for v in row_vals):
                        break
                    run.append(row_vals)
                    r -= 1
                if not run:
                    continue
                run.reverse()  # from adjacent outward
                max_len = base_r + 1  # distance to top edge
                add_slice(name, base_r, c_start, run, len(run), max_len)

            elif name == 'D':
                base_r = y1 + 1
                base_cs = [c for c in range(x0, x1 + 1) if base_r < h and grid[base_r][c] != 8 and grid[base_r][c] != 1]
                if not base_cs:
                    continue
                if len(base_cs) > 1:
                    if any(base_cs[i+1] - base_cs[i] != 1 for i in range(len(base_cs)-1)):
                        continue
                c_start = base_cs[0]
                c_width = len(base_cs)
                run = []
                r = base_r
                while r < h:
                    row_vals = tuple(grid[r][c_start + k] for k in range(c_width))
                    if any(v == 8 or v == 1 for v in row_vals):
                        break
                    run.append(row_vals)
                    r += 1
                if not run:
                    continue
                max_len = h - base_r
                add_slice(name, base_r, c_start, run, len(run), max_len)

            elif name == 'R':
                base_c = x1 + 1
                base_rs = [r for r in range(y0, y1 + 1) if base_c < w and grid[r][base_c] != 8 and grid[r][base_c] != 1]
                if not base_rs:
                    continue
                if len(base_rs) > 1:
                    if any(base_rs[i+1] - base_rs[i] != 1 for i in range(len(base_rs)-1)):
                        continue
                r_start = base_rs[0]
                r_width = len(base_rs)
                run = []
                c = base_c
                while c < w:
                    col_vals = tuple(grid[r_start + k][c] for k in range(r_width))
                    if any(v == 8 or v == 1 for v in col_vals):
                        break
                    run.append(col_vals)
                    c += 1
                if not run:
                    continue
                max_len = w - base_c
                add_slice(name, r_start, base_c, run, len(run), max_len)

            elif name == 'L':
                base_c = x0 - 1
                base_rs = [r for r in range(y0, y1 + 1) if base_c >= 0 and grid[r][base_c] != 8 and grid[r][base_c] != 1]
                if not base_rs:
                    continue
                if len(base_rs) > 1:
                    if any(base_rs[i+1] - base_rs[i] != 1 for i in range(len(base_rs)-1)):
                        continue
                r_start = base_rs[0]
                r_width = len(base_rs)
                run = []
                c = base_c
                while c >= 0:
                    col_vals = tuple(grid[r_start + k][c] for k in range(r_width))
                    if any(v == 8 or v == 1 for v in col_vals):
                        break
                    run.append(col_vals)
                    c -= 1
                if not run:
                    continue
                run.reverse()
                max_len = base_c + 1
                add_slice(name, r_start, base_c, run, len(run), max_len)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Connected components of 1s (8-connected)
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == 1:
                                seen[ny][nx] = True
                                stack.append((ny, nx))
                comps.append(cells)

    out = [row[:] for row in grid]

    # Process components from top-left to bottom-right; this makes later
    # (more bottom/right) extensions overwrite earlier ones at crossings.
    def key(cells):
        return (min(y for y, _ in cells), min(x for _, x in cells), cells)

    for cells in sorted(comps, key=key):
        y0 = min(y for y, _ in cells)
        y1 = max(y for y, _ in cells)
        x0 = min(x for _, x in cells)
        x1 = max(x for _, x in cells)
        comp_set = set(cells)

        # Candidate extensions: (direction, start line adjacent to the 1-object,
        # start row/col, existing slices, existing_len, max_len)
        candidates = []

        # Directions: U, R, D, L.  Only vertical directions are needed for the
        # observed/tested rule, but keep structure general.
        # For vertical tails, use the actual contiguous 1-cells on the top/bottom
        # boundary row, not the whole bounding box.

        # Up
        if y0 > 0:
            side_cols = [c for c in range(x0, x1 + 1) if (y0, c) in comp_set]
            if side_cols:
                side_cols = sorted(set(side_cols))
                # require contiguous
                if all(side_cols[i + 1] - side_cols[i] == 1 for i in range(len(side_cols) - 1)):
                    run = []
                    r = y0 - 1
                    while r >= 0:
                        vals = [grid[r][c] for c in side_cols]
                        if any(v == 8 or v == 1 for v in vals):
                            break
                        run.append(tuple(vals))
                        r -= 1
                    if run:
                        run.reverse()
                        existing_len = len(run)
                        max_len = y0
                        if max_len > existing_len:
                            candidates.append(('U', y0 - 1, side_cols[0], run, existing_len, max_len))

        # Down
        if y1 < h - 1:
            side_cols = [c for c in range(x0, x1 + 1) if (y1, c) in comp_set]
            if side_cols:
                side_cols = sorted(set(side_cols))
                if all(side_cols[i + 1] - side_cols[i] == 1 for i in range(len(side_cols) - 1)):
                    run = []
                    r = y1 + 1
                    while r < h:
                        vals = [grid[r][c] for c in side_cols]
                        if any(v == 8 or v == 1 for v in vals):
                            break
                        run.append(tuple(vals))
                        r += 1
                    if run:
                        existing_len = len(run)
                        max_len = h - (y1 + 1)
                        if max_len > existing_len:
                            candidates.append(('D', y1 + 1, side_cols[0], run, existing_len, max_len))

        # Horizontal tails are not needed for the given examples/test, but can be
        # handled similarly if present.
        # Left
        if x0 > 0:
            side_rows = [r for r in range(y0, y1 + 1) if (r, x0) in comp_set]
            if side_rows:
                side_rows = sorted(set(side_rows))
                if all(side_rows[i + 1] - side_rows[i] == 1 for i in range(len(side_rows) - 1)):
                    run = []
                    c = x0 - 1
                    while c >= 0:
                        vals = [grid[r][c] for r in side_rows]
                        if any(v == 8 or v == 1 for v in vals):
                            break
                        run.append(tuple(vals))
                        c -= 1
                    if run:
                        run.reverse()
                        existing_len = len(run)
                        max_len = x0
                        if max_len > existing_len:
                            candidates.append(('L', side_rows[0], x0 - 1, run, existing_len, max_len))

        # Right
        if x1 < w - 1:
            side_rows = [r for r in range(y0, y1 + 1) if (r, x1) in comp_set]
            if side_rows:
                side_rows = sorted(set(side_rows))
                if all(side_rows[i + 1] - side_rows[i] == 1 for i in range(len(side_rows) - 1)):
                    run = []
                    c = x1 + 1
                    while c < w:
                        vals = [grid[r][c] for r in side_rows]
                        if any(v == 8 or v == 1 for v in vals):
                            break
                        run.append(tuple(vals))
                        c += 1
                    if run:
                        existing_len = len(run)
                        max_len = w - (x1 + 1)
                        if max_len > existing_len:
                            candidates.append(('R', side_rows[0], x1 + 1, run, existing_len, max_len))

        for direction, a, b, slices, existing_len, max_len in candidates:
            # Smallest repeating period of the slice sequence.
            period = 1
            while period <= existing_len:
                ok = True
                for i in range(period, existing_len):
                    if slices[i] != slices[i - period]:
                        ok = False
                        break
                if ok:
                    break
                period += 1

            if direction == 'U':
                top_row, c0 = a, b
                width = len(slices[0])
                for dist in range(existing_len, max_len):
                    r = top_row - (dist - existing_len)
                    sl = slices[dist % period]
                    for k, val in enumerate(sl):
                        if 0 <= r < h and 0 <= c0 + k < w:
                            out[r][c0 + k] = val
            elif direction == 'D':
                top_row, c0 = a, b
                width = len(slices[0])
                for dist in range(existing_len, max_len):
                    r = top_row + (dist - existing_len)
                    sl = slices[dist % period]
                    for k, val in enumerate(sl):
                        if 0 <= r < h and 0 <= c0 + k < w:
                            out[r][c0 + k] = val
            elif direction == 'L':
                r0, left_col = a, b
                height = len(slices[0])
                for dist in range(existing_len, max_len):
                    c = left_col - (dist - existing_len)
                    sl = slices[dist % period]
                    for k, val in enumerate(sl):
                        if 0 <= r0 + k < h and 0 <= c < w:
                            out[r0 + k][c] = val
            elif direction == 'R':
                r0, left_col = a, b
                height = len(slices[0])
                for dist in range(existing_len, max_len):
                    c = left_col + (dist - existing_len)
                    sl = slices[dist % period]
                    for k, val in enumerate(sl):
                        if 0 <= r0 + k < h and 0 <= c < w:
                            out[r0 + k][c] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    background = g[0, 0]

    # 8-connected components of non-background colours
    seen = np.zeros((h, w), dtype=bool)
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r, c] or g[r, c] == background:
                continue
            color = g[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
            components.append((color, cells))

    by_color = {}
    for color, cells in components:
        by_color.setdefault(color, []).append(cells)

    def is_solid_5x5(cells):
        if len(cells) != 25:
            return False
        ys = [r for r, _ in cells]
        xs = [c for _, c in cells]
        if max(ys) - min(ys) != 4 or max(xs) - min(xs) != 4:
            return False
        s = set(cells)
        y0, x0 = min(ys), min(xs)
        return all((y0 + dy, x0 + dx) in s for dy in range(5) for dx in range(5))

    selected = []
    for color, comps in by_color.items():
        solids = [cells for cells in comps if is_solid_5x5(cells)]
        patterns = [cells for cells in comps if not is_solid_5x5(cells)]
        if len(solids) == 1 and len(patterns) >= 1:
            sr, sc = zip(*solids[0])
            selected.append((min(sr), min(sc), color, patterns))

    if not selected:
        return [list(map(int, row)) for row in g]

    # Infer the layout grid formed by the solid 5x5 squares.
    rows = sorted({r // 7 for _, r, _, _ in selected})
    cols = sorted({c // 7 for _, _, c, _ in selected})
    row_idx = {r: i for i, r in enumerate(rows)}
    col_idx = {c: i for i, c in enumerate(cols)}

    H = 13 * len(rows) + 1
    W = 13 * len(cols) + 1
    out = np.full((H, W), background, dtype=int)

    for _, sr, sc, color, patterns in selected:
        if not patterns:
            continue

        # Choose the non-solid component of this colour.
        # If several exist, use the one with the smallest bounding box
        # (all examples use a 3x3 pattern object).
        pattern = min(
            patterns,
            key=lambda cells: (
                max(r for r, _ in cells) - min(r for r, _ in cells),
                max(c for _, c in cells) - min(c for _, c in cells),
            )
        )

        pset = set(pattern)
        pys = [r for r, _ in pattern]
        pxs = [c for _, c in pattern]
        p_top, p_bottom = min(pys), max(pys)
        p_left, p_right = min(pxs), max(pxs)

        # Create a 5x5 solid square, then punch holes using the pattern.
        block5 = np.full((5, 5), color, dtype=int)
        for pr in range(p_top, p_bottom + 1):
            for pc in range(p_left, p_right + 1):
                if (pr, pc) in pset:
                    # Map the pattern bounding box onto the central 3x3 area.
                    if p_bottom == p_top:
                        ry = 2
                    else:
                        ry = 1 + round(2 * (pr - p_top) / (p_bottom - p_top))
                    if p_right == p_left:
                        rx = 2
                    else:
                        rx = 1 + round(2 * (pc - p_left) / (p_right - p_left))
                    block5[ry, rx] = background

        # Full 7x7 tile with background border.
        tile = np.full((7, 7), background, dtype=int)
        tile[1:6, 1:6] = block5

        # Place tiles on a shared-border grid.
        ti = row_idx[sr // 7]
        tj = col_idx[sc // 7]
        top = 6 * ti
        left = 6 * tj
        out[top:top + 7, left:left + 7] = tile

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter, defaultdict

    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Candidate background colours must touch all four borders.
    candidates = set()
    for r in range(H):
        candidates.add(a[r, 0])
        candidates.add(a[r, W - 1])
    for c in range(W):
        candidates.add(a[0, c])
        candidates.add(a[H - 1, c])
    candidates.discard(0)

    # Connected components (4-connected), ignoring the chosen background.
    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        Hm, Wm = mask.shape
        for r in range(Hm):
            for c in range(Wm):
                if mask[r, c] and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < Hm and 0 <= nx < Wm:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                    comps.append(cells)
        return comps

    def bbox(cells):
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        return min(ys), max(ys), min(xs), max(xs)

    def area(cells):
        return len(cells)

    def color_of(cells):
        return a[cells[0][0], cells[0][1]]

    def holes_in_bbox(cells, bg):
        r1, r2, c1, c2 = bbox(cells)
        return sum(1 for r in range(r1, r2 + 1) for c in range(c1, c2 + 1) if a[r, c] == bg)

    def score(bg, comp):
        if color_of(comp) == bg:
            return None
        h = holes_in_bbox(comp, bg)
        outside = sum(1 for r in range(H) for c in range(W)
                      if a[r, c] not in (0, bg) and (r, c) not in comp)
        return outside - h

    def fit_score(bg, frame, others):
        if not frame or not others:
            return -1
        r1, r2, c1, c2 = bbox(frame)
        h = holes_in_bbox(frame, bg)

        # Total cells to place, excluding background, frame colour, and 0 unless 0 is frame colour.
        target = 0
        for r in range(H):
            for c in range(W):
                v = a[r, c]
                if v == bg or v == color_of(frame):
                    continue
                if v == 0 and color_of(frame) != 0:
                    continue
                target += 1

        # Use cells of colours other than background/frame/0 (0 handled separately).
        placed = 0
        for r in range(H):
            for c in range(W):
                v = a[r, c]
                if v == bg or v == color_of(frame) or v == 0:
                    continue
                placed += 1

        zero_cells = 0
        for r in range(H):
            for c in range(W):
                if a[r, c] == 0:
                    zero_cells += 1

        # The exact fit is usually perfect; prefer small residual.
        return abs(placed + zero_cells - h)

    best = None

    for bg in candidates:
        comp_list = components(a == bg)
        if not comp_list:
            continue

        # The background component is usually the largest border-connected component.
        bg_comp = max(comp_list, key=area)
        frame_components = [comp for comp in comp_list if comp is not bg_comp]

        # Try each non-background component as the frame.
        for frame in frame_components:
            s = score(bg, frame)
            if s is None:
                continue
            others = [comp for comp in frame_components if comp is not frame]
            fs = fit_score(bg, frame, others)
            cand = (s, fs, -area(frame), bg, frame)
            if best is None or cand < best:
                best = cand

    if best is None:
        # Fallback: return original as a list of ints.
        return [[int(x) for x in row] for row in grid]

    _, _, _, bg, frame = best
    r1, r2, c1, c2 = bbox(frame)
    out = np.full((r2 - r1 + 1, c2 - c1 + 1), int(bg), dtype=int)

    frame_mask = np.zeros_like(a, dtype=bool)
    for r, c in frame:
        frame_mask[r, c] = True

    # Collect non-background, non-frame cells, with 0 included only when it is not the frame colour.
    cells_to_place = []
    for r in range(H):
        for c in range(W):
            v = int(a[r, c])
            if v == bg or frame_mask[r, c]:
                continue
            if v == 0 and int(a[frame[0][0], frame[0][1]]) != 0:
                continue
            cells_to_place.append((r, c, v))

    # Stable reading-order placement into holes of the frame bounding box.
    holes = []
    for r in range(r1, r2 + 1):
        for c in range(c1, c2 + 1):
            if a[r, c] == bg:
                holes.append((r, c))

    # If there are more holes than cells, fill as far as possible; if fewer, stop when cells run out.
    n = min(len(holes), len(cells_to_place))
    for i in range(n):
        hr, hc = holes[i]
        out[hr - r1, hc - c1] = cells_to_place[i][2]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter, defaultdict

    a = np.array(grid, dtype=int)
    H, W = a.shape

    # 4-connected component labeling
    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                    comps.append(cells)
        return comps

    def bbox(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return min(ys), max(ys), min(xs), max(xs)

    # The frame is a closed rectangle made of one colour:
    # its top and bottom rows are completely that colour, and its left/right
    # columns are completely that colour.
    best = None  # (score, frame_color, r1, r2, c1, c2)

    for colour in set(a.flat):
        m = (a == colour)
        # Candidate top rows: entirely colour.
        top_candidates = [r for r in range(H) if m[r, :].all()]
        # Candidate bottom rows: entirely colour.
        bottom_candidates = [r for r in range(H) if m[r, :].all()]

        for r1 in top_candidates:
            for r2 in bottom_candidates:
                if r2 <= r1:
                    continue
                # Left column completely colour in [r1, r2]
                left_cols = [c for c in range(W) if m[r1:r2 + 1, c].all()]
                right_cols = [c for c in range(W) if m[r1:r2 + 1, c].all()]
                if not left_cols or not right_cols:
                    continue
                c1 = left_cols[0]
                c2 = right_cols[-1]
                if c2 <= c1:
                    continue
                if not (m[r1, c1:c2 + 1].all() and m[r2, c1:c2 + 1].all()):
                    continue
                if not (m[r1:r2 + 1, c1].all() and m[r1:r2 + 1, c2].all()):
                    continue

                # Interior cells (excluding border) that are holes for other objects.
                holes = 0
                for r in range(r1 + 1, r2):
                    for c in range(c1 + 1, c2):
                        if a[r, c] != colour:
                            holes += 1

                # Payload = every cell that is neither frame colour nor 0.
                payload = 0
                for r in range(H):
                    for c in range(W):
                        v = a[r, c]
                        if v != colour and v != 0:
                            payload += 1

                # Prefer the rectangle whose hole count matches payload exactly.
                # If not exact, prefer larger overlap / smaller mismatch.
                score = (holes != payload, abs(holes - payload), -holes)
                if best is None or score < best[0]:
                    best = (score, colour, r1, r2, c1, c2)

    if best is None:
        # Fallback: return unchanged as Python ints.
        return [[int(x) for x in row] for row in grid]

    _, frame, r1, r2, c1, c2 = best
    out = a[r1:r2 + 1, c1:c2 + 1].copy()

    # Payload cells in reading order, preserving connected objects implicitly.
    payload_cells = []
    for r in range(H):
        for c in range(W):
            v = int(a[r, c])
            if v != frame and v != 0:
                payload_cells.append(v)

    # Fill interior holes (all non-frame cells inside the rectangle) in reading order.
    idx = 0
    for r in range(r1, r2 + 1):
        for c in range(c1, c2 + 1):
            if a[r, c] != frame and idx < len(payload_cells):
                out[r - r1, c - c1] = payload_cells[idx]
                idx += 1

    return [[int(x) for x in row] for row in out.tolist()]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = a.copy()

    bg = 8

    def set_bg(y, x, v):
        if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
            out[y, x] = v

    # Detect 2-column "vertical" devices.
    # In the examples these have height 7 or 9 and a right-hand or left-hand
    # column filled mostly with 2s (height 7) or 1s (height 9).
    for y in range(H - 1):
        for x in range(W - 1):
            cells = [
                (y, x), (y + 1, x),
                (y, x + 1), (y + 1, x + 1)
            ]
            if all(a[r, c] != bg for r, c in cells):
                # Try to determine the full 2-column component.
                mask = np.zeros((H, W), dtype=bool)
                mask[y, x] = True
                stack = [(y, x)]
                while stack:
                    cy, cx = stack.pop()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = cy + dy, cx + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not mask[ny, nx] and a[ny, nx] != bg:
                                    mask[ny, nx] = True
                                    stack.append((ny, nx))

                ys, xs = np.where(mask)
                if xs.max() - xs.min() != 1:
                    continue
                if ys.max() - ys.min() not in (6, 8):  # height 7 or 9
                    continue

                left, right = xs.min(), xs.max()
                top, bottom = ys.min(), ys.max()
                h = bottom - top + 1

                left_col = [a[r, left] for r in range(top, bottom + 1)]
                right_col = [a[r, right] for r in range(top, bottom + 1)]

                # The emitting side is the side whose column contains the
                # repeating low digit (2 for height 7, 1 for height 9).
                if h == 7:
                    if left_col.count(2) >= 4:
                        side = -1
                        rows = [1, 4, 5]
                        colors = [6, 5, 1]
                    elif right_col.count(2) >= 4:
                        side = 1
                        rows = [1, 4, 5]
                        colors = [6, 5, 1]
                    else:
                        continue
                else:  # h == 9
                    if left_col.count(1) >= 5:
                        side = -1
                        rows = [1, 3, 5]
                        colors = [3, 6, 9]
                    elif right_col.count(1) >= 5:
                        side = 1
                        rows = [1, 3, 5]
                        colors = [3, 6, 9]
                    else:
                        continue

                for off, col in zip(rows, colors):
                    r = top + off
                    if side == -1:
                        c = left - 1
                    else:
                        c = right + 1
                    while 0 <= c < W and out[r, c] == bg:
                        out[r, c] = col
                        c += side

    # Detect single-cell anchors of colors 1, 5, 6, 9.
    # They emit vertical three-line beams upward or downward.
    for y in range(H):
        for x in range(W):
            if a[y, x] in (1, 5, 6, 9):
                # Make sure it is isolated in the input.
                isolated = True
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and (ny, nx) != (y, x):
                            if a[ny, nx] != bg:
                                isolated = False
                                break
                    if not isolated:
                        break
                if not isolated:
                    continue

                # Direction: upward if anchor is in the lower half, else downward.
                dy = -1 if y > H // 2 else 1

                # Beam extent: paint from the anchor row until just before
                # the first non-background cell in the central column.
                if dy == -1:
                    stop = 0
                    yy = y - 1
                    while 0 <= yy < H and a[yy, x] == bg:
                        stop = yy
                        yy -= 1
                    rows = range(stop, y + 1)
                else:
                    stop = H - 1
                    yy = y + 1
                    while 0 <= yy < H and a[yy, x] == bg:
                        stop = yy
                        yy += 1
                    rows = range(y, stop + 1)

                if a[y, x] == 1:
                    # Example 1: anchor 1 makes columns x, x+1, x+3
                    for r in rows:
                        set_bg(r, x, 1)
                        set_bg(r, x + 1, 5)
                        set_bg(r, x + 3, 6)
                elif a[y, x] == 5:
                    # Example 1: anchor 5 makes columns x-1, x, x+3
                    for r in rows:
                        set_bg(r, x - 1, 1)
                        set_bg(r, x, 5)
                        set_bg(r, x + 3, 6)
                elif a[y, x] == 6:
                    # Example 2: anchor 6 makes columns x-2, x, x+2
                    for r in rows:
                        set_bg(r, x - 2, 9)
                        set_bg(r, x, 6)
                        set_bg(r, x + 2, 3)
                elif a[y, x] == 9:
                    # Not used in provided examples; choose a consistent palette.
                    for r in rows:
                        set_bg(r, x - 2, 6)
                        set_bg(r, x, 9)
                        set_bg(r, x + 2, 3)

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    A = np.array(grid, dtype=int)
    colors = set(int(x) for row in A for x in row)
    bg_mode = 0
    bg_count = -1
    for c in colors:
        cnt = int(np.sum(A == c))
        if cnt > bg_count:
            bg_count = cnt
            bg_mode = c

    def connected_components(mask):
        visited = np.zeros_like(mask, dtype=bool)
        comps = []
        for i in range(H):
            for j in range(W):
                if mask[i, j] and not visited[i, j]:
                    q = deque([(i, j)])
                    visited[i, j] = True
                    pts = []
                    while q:
                        r, c = q.popleft()
                        pts.append((r, c))
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < H and 0 <= nc < W and mask[nr, nc] and not visited[nr, nc]:
                                    visited[nr, nc] = True
                                    q.append((nr, nc))
                    comps.append(pts)
        return comps

    # Candidate template objects: non-background solid color components.
    candidates = []
    for c in colors:
        if c == bg_mode:
            continue
        mask = (A == c)
        for pts in connected_components(mask):
            ys = [p[0] for p in pts]
            xs = [p[1] for p in pts]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            h = r1 - r0 + 1
            w = c1 - c0 + 1
            area = len(pts)
            bbox_area = h * w
            # The template should be mostly solid and have interior holes.
            if area >= 100 and bbox_area - area >= 5 and bbox_area - area <= bbox_area * 0.6:
                candidates.append((bbox_area, area, c, r0, r1, c0, c1, pts))

    if not candidates:
        return [list(row) for row in A]

    # Choose the largest template (break ties by larger hole count, then position).
    candidates.sort(key=lambda x: (x[0], x[1], -x[3], -x[5]), reverse=True)
    _, _, temp_color, tr0, tr1, tc0, tc1, _ = candidates[0]

    # Small reference objects, excluding the chosen template component.
    ref_objects = []
    for c in colors:
        if c == bg_mode or c == temp_color:
            continue
        mask = (A == c)
        for pts in connected_components(mask):
            ref_objects.append((c, pts))

    def normalize_shape(pts):
        ys = [p[0] for p in pts]
        xs = [p[1] for p in pts]
        y0, x0 = min(ys), min(xs)
        norm = tuple(sorted((y - y0, x - x0) for y, x in pts))
        return len(norm), norm

    def orientations(pts):
        ys = [p[0] for p in pts]
        xs = [p[1] for p in pts]
        y0, x0 = min(ys), min(xs)
        arr = set((y - y0, x - x0) for y, x in pts)
        results = []
        cur = arr
        for _ in range(4):
            h = max(y for y, x in cur) + 1
            w = max(x for y, x in cur) + 1
            rot = tuple(sorted((x, h - 1 - y) for y, x in cur))
            results.append(rot)
            cur = set(rot)
        seen = set()
        uniq = []
        for s in results:
            if s not in seen:
                seen.add(s)
                uniq.append(s)
        return uniq

    def shape_key(pts):
        size, _ = normalize_shape(pts)
        return (size, tuple(sorted(orientations(pts))))

    # Determine mask of holes inside the template bounding box.
    # Holes are background cells that are not reachable from outside the bounding box.
    out_h = tr1 - tr0 + 1
    out_w = tc1 - tc0 + 1
    temp_mask_box = (A[tr0:tr1 + 1, tc0:tc1 + 1] == temp_color)
    # In-box cells that are not template color and are background.
    box_bg = (A[tr0:tr1 + 1, tc0:tc1 + 1] == bg_mode)

    # Flood fill from outside the bounding box over background cells.
    outside_visited = np.zeros((H, W), dtype=bool)
    q = deque()
    for r in range(H):
        for c in range(W):
            if A[r, c] == bg_mode and not (tr0 <= r <= tr1 and tc0 <= c <= tc1):
                # only need to seed border/background connected to outside
                pass
    # Simpler: flood fill background on whole grid, holes are background cells whose
    # component does not touch grid border.
    outside = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in (0, W - 1):
            if A[r, c] == bg_mode and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))
    for c in range(W):
        for r in (0, H - 1):
            if A[r, c] == bg_mode and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and A[nr, nc] == bg_mode and not outside[nr, nc]:
                    outside[nr, nc] = True
                    q.append((nr, nc))

    hole_box = box_bg & (~outside[tr0:tr1 + 1, tc0:tc1 + 1])

    # Connected hole components within the box.
    visited = np.zeros_like(hole_box, dtype=bool)
    hole_comps = []
    for r in range(out_h):
        for c in range(out_w):
            if hole_box[r, c] and not visited[r, c]:
                q = deque([(r, c)])
                visited[r, c] = True
                pts = []
                while q:
                    rr, cc = q.popleft()
                    pts.append((rr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < out_h and 0 <= nc < out_w and hole_box[nr, nc] and not visited[nr, nc]:
                                visited[nr, nc] = True
                                q.append((nr, nc))
                hole_comps.append(pts)

    # Build candidate color mappings from reference objects.
    # A reference object can match a hole component if its shape can be oriented
    # to the hole component and it is the unique color for that oriented shape
    # among all references, or at least consistently matches.
    refs = []
    for c, pts in ref_objects:
        size, norm = normalize_shape(pts)
        ors = tuple(sorted(orientations(pts)))
        refs.append((c, size, ors, pts))

    # For each hole component, find colors whose some reference object has same
    # shape up to rotation/reflection. Prefer colors that are unique for the shape.
    color_for_hole = [None] * len(hole_comps)
    for idx, hpts in enumerate(hole_comps):
        h_or = tuple(sorted(orientations(hpts)))
        candidates_for_shape = []
        for c, size, ors, _ in refs:
            if ors == h_or:
                if c not in candidates_for_shape:
                    candidates_for_shape.append(c)
        if len(candidates_for_shape) == 1:
            color_for_hole[idx] = candidates_for_shape[0]
        elif len(candidates_for_shape) > 1:
            # If multiple colors match, prefer the color that has exactly the same
            # number of objects as the number of hole components of this shape.
            count_needed = sum(1 for hp in hole_comps if tuple(sorted(orientations(hp))) == h_or)
            best = None
            best_score = -1
            for c in candidates_for_shape:
                count_obj = sum(1 for cc, size, ors, _ in refs if cc == c and ors == h_or)
                score = 0
                if count_obj == count_needed:
                    score += 100
                # Prefer colors appearing in outputs? Not known. Use count closeness.
                score -= abs(count_obj - count_needed)
                # Slight preference for larger objects.
                score += max(0, size - 1) / 1000.0
                if score > best_score:
                    best_score = score
                    best = c
            color_for_hole[idx] = best

    # If any unmapped components remain, use majority of remaining reference colors
    # not already used for other shapes, fallback to any matching shape.
    if any(c is None for c in color_for_hole):
        for idx, hpts in enumerate(hole_comps):
            if color_for_hole[idx] is None:
                h_or = tuple(sorted(orientations(hpts)))
                for c, size, ors, _ in refs:
                    if ors == h_or:
                        color_for_hole[idx] = c
                        break
                if color_for_hole[idx] is None:
                    color_for_hole[idx] = bg_mode

    # Construct output.
    out = np.full((out_h, out_w), temp_color, dtype=int)
    for idx, hpts in enumerate(hole_comps):
        c = int(color_for_hole[idx])
        for r, cc in hpts:
            out[r, cc] = c

    return [list(row) for row in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine background as the most common color.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (8-connected).
    visited = np.zeros((h, w), dtype=bool)
    objects = []

    def get_component(r0, c0):
        color = g[r0, c0]
        q = [(r0, c0)]
        visited[r0, c0] = True
        cells = []
        while q:
            r, c = q.pop()
            cells.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and g[nr, nc] == color:
                        visited[nr, nc] = True
                        q.append((nr, nc))
        return color, cells

    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not visited[r, c]:
                color, cells = get_component(r, c)
                objects.append((color, cells))

    out = np.full((h, w), bg, dtype=int)

    def move_to_top(cells):
        rmin = min(r for r, _ in cells)
        for r, c in cells:
            out[r - rmin, c] = g[r, c]

    def move_to_bottom(cells):
        rmax = max(r for r, _ in cells)
        for r, c in cells:
            out[h - 1 - (rmax - r), c] = g[r, c]

    # Primary observed rule: move the component upward if its color is odd,
    # otherwise downward.  Tie-breakers are kept for robustness on variants.
    for color, cells in objects:
        if color % 2 == 1:
            move_to_top(cells)
        else:
            move_to_bottom(cells)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    visited = np.zeros((h, w), dtype=bool)
    objs = []

    def component(r0, c0):
        col = g[r0, c0]
        stack = [(r0, c0)]
        visited[r0, c0] = True
        cells = []
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and g[nr, nc] == col:
                        visited[nr, nc] = True
                        stack.append((nr, nc))
        return col, cells

    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not visited[r, c]:
                objs.append(component(r, c))

    def move_up(cells):
        rmin = min(r for r, _ in cells)
        for r, c in cells:
            yield r - rmin, c

    def move_down(cells):
        rmax = max(r for r, _ in cells)
        for r, c in cells:
            yield h - 1 - (rmax - r), c

    def move_left(cells):
        cmin = min(c for _, c in cells)
        for r, c in cells:
            yield r, c - cmin

    def move_right(cells):
        cmax = max(c for _, c in cells)
        for r, c in cells:
            yield r, w - 1 - (cmax - c)

    out = np.full((h, w), bg, dtype=int)

    def place(cells, target):
        for rr, cc in target:
            out[rr, cc] = g[cells[0][0], cells[0][1]]

    for color, cells in objs:
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)

        # 1) Strong horizontal asymmetry: move left/right.
        left_mass = sum(1 for r, c in cells if c < (cmin + cmax) / 2.0)
        right_mass = sum(1 for r, c in cells if c > (cmin + cmax) / 2.0)
        if abs(left_mass - right_mass) >= 2:
            if left_mass > right_mass:
                place(cells, move_left(cells))
            else:
                place(cells, move_right(cells))
            continue

        # 2) Otherwise use vertical tendency.
        mid = (rmin + rmax) / 2.0
        top_mass = sum(1 for r, c in cells if r < mid)
        bottom_mass = sum(1 for r, c in cells if r > mid)

        if bottom_mass - top_mass >= 1:
            place(cells, move_down(cells))
        elif top_mass - bottom_mass >= 1:
            place(cells, move_up(cells))
        else:
            # Symmetric vertically: prefer the edge closer to the object's
            # centroid; tie-breaker is color parity.
            top_dist = (sum(r for r, _ in cells) / len(cells)) - rmin
            bottom_dist = rmax - (sum(r for r, _ in cells) / len(cells))
            if top_dist < bottom_dist:
                place(cells, move_up(cells))
            elif bottom_dist < top_dist:
                place(cells, move_down(cells))
            else:
                if color % 2 == 1:
                    place(cells, move_up(cells))
                else:
                    place(cells, move_down(cells))

    return out.tolist()

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    out = [[8] * W for _ in range(H)]

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    def flood(r, c, color, comp_id):
        """Return list of cells of connected component with 4-connectivity."""
        stack = [(r, c)]
        cells = []
        while stack:
            cr, cc = stack.pop()
            if not in_bounds(cr, cc) or out[cr][cc] != 0 or grid[cr][cc] != color:
                continue
            out[cr][cc] = 1  # mark visited
            cells.append((cr, cc))
            stack.extend([(cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)])
        return cells

    # Reusable marker array for components / visited.
    visited = [[0] * W for _ in range(H)]

    # Identify color-1 objects (4-connected is enough for these solid blobs).
    objects = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1 and not visited[r][c]:
                cells = flood(r, c, 1, 0)
                rs = [x[0] for x in cells]
                cs = [x[1] for x in cells]
                objects.append({
                    "cells": set(cells),
                    "rmin": min(rs), "rmax": max(rs),
                    "cmin": min(cs), "cmax": max(cs),
                })

    # Associate every color-3 cell with the nearest color-1 object and a direction.
    # Direction is the side of the object's bounding box where the 3 cell lies.
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 3:
                continue
            best_obj = None
            best_dir = None
            best_d2 = None
            for obj in objects:
                # nearest point in object's bounding box
                rr = max(obj["rmin"], min(r, obj["rmax"]))
                cc = max(obj["cmin"], min(c, obj["cmax"]))
                d2 = (r - rr) ** 2 + (c - cc) ** 2
                # Require adjacency (Chebyshev distance <= 1) to avoid ambiguity.
                if d2 <= 1:
                    if best_d2 is None or d2 < best_d2:
                        best_d2 = d2
                        if r < obj["rmin"]:
                            best_dir = "up"
                        elif r > obj["rmax"]:
                            best_dir = "down"
                        elif c < obj["cmin"]:
                            best_dir = "left"
                        elif c > obj["cmax"]:
                            best_dir = "right"
                        else:
                            # 3-cell overlapping object bbox (should not happen);
                            # infer by majority of nearest object cells.
                            best_dir = "up"
                        best_obj = obj
            if best_obj is not None and best_dir is not None:
                best_obj.setdefault("sides", {}).setdefault(best_dir, []).append((r, c))

    # Initial 2/4 seed: a short line. 4 is usually at one end.
    seed_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (2, 4):
                seed_cells.append((r, c))

    active = [False] * len(objects)

    def object_at(r, c):
        for i, obj in enumerate(objects):
            if (r, c) in obj["cells"]:
                return i
        return -1

    def activate(obj_idx):
        if obj_idx is None or obj_idx < 0 or obj_idx >= len(objects):
            return
        if active[obj_idx]:
            return
        active[obj_idx] = True
        for r, c in objects[obj_idx]["cells"]:
            out[r][c] = 2

    def paint(r, c):
        if in_bounds(r, c):
            out[r][c] = 2

    def cast_from_seed():
        if not seed_cells:
            return
        rows = [r for r, _ in seed_cells]
        cols = [c for _, c in seed_cells]
        vertical = len(set(rows)) >= len(set(cols))

        if vertical:
            c = cols[0]
            rmin = min(rows)
            rmax = max(rows)
            # Extend upward from the top of seed.
            for r in range(rmin - 1, -1, -1):
                oi = object_at(r, c)
                if oi != -1:
                    activate(oi)
                    paint(r, c)
                    break
                paint(r, c)
            # Extend downward from the bottom of seed.
            for r in range(rmax + 1, H):
                oi = object_at(r, c)
                if oi != -1:
                    activate(oi)
                    paint(r, c)
                    break
                paint(r, c)
        else:
            r = rows[0]
            cmin = min(cols)
            cmax = max(cols)
            # Extend leftward.
            for c in range(cmin - 1, -1, -1):
                oi = object_at(r, c)
                if oi != -1:
                    activate(oi)
                    paint(r, c)
                    break
                paint(r, c)
            # Extend rightward.
            for c in range(cmax + 1, W):
                oi = object_at(r, c)
                if oi != -1:
                    activate(oi)
                    paint(r, c)
                    break
                paint(r, c)

        # Paint seed itself.
        for r, c in seed_cells:
            paint(r, c)

    cast_from_seed()

    # BFS over activated objects, casting rays from their color-3 sides.
    q = deque(i for i, a in enumerate(active) if a)
    cast_done = [[False] * len(objects) for _ in range(4)]  # not strictly needed but safe
    dir_index = {"up": 0, "down": 1, "left": 2, "right": 3}

    while q:
        oi = q.popleft()
        obj = objects[oi]
        sides = obj.get("sides", {})

        for direction, cells in sides.items():
            # Only use cells that were originally 3 and adjacent to this object.
            cells = [(r, c) for r, c in cells if grid[r][c] == 3]
            if not cells:
                continue

            if direction == "up":
                for (r0, c0) in cells:
                    for r in range(r0, -1, -1):
                        o = object_at(r, c0)
                        if o != -1 and o != oi:
                            paint(r, c0)
                            activate(o)
                            break
                        paint(r, c0)
            elif direction == "down":
                for (r0, c0) in cells:
                    for r in range(r0, H):
                        o = object_at(r, c0)
                        if o != -1 and o != oi:
                            paint(r, c0)
                            activate(o)
                            break
                        paint(r, c0)
            elif direction == "left":
                for (r0, c0) in cells:
                    for c in range(c0, -1, -1):
                        o = object_at(r0, c)
                        if o != -1 and o != oi:
                            paint(r0, c)
                            activate(o)
                            break
                        paint(r0, c)
            elif direction == "right":
                for (r0, c0) in cells:
                    for c in range(c0, W):
                        o = object_at(r0, c)
                        if o != -1 and o != oi:
                            paint(r0, c)
                            activate(o)
                            break
                        paint(r0, c)

        # Newly activated objects are appended by activate(); collect them.
        for i, a in enumerate(active):
            if a and i not in q:
                q.append(i)

    return out

