            q = deque([(sr, sc)])
            owner[sr][sc] = idx
            seen = [(sr, sc)]

            while q:
                r, c = q.popleft()
                col = grid[r][c]
                node_cells[idx].append((r, c))
                if col == 1:
                    node_body_cells[idx].append((r, c))
                else:
                    node_ports[idx].append((r, c))

                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if inb(nr, nc) and owner[nr][nc] == -1 and grid[nr][nc] in (1, 3):
                        owner[nr][nc] = idx
                        q.append((nr, nc))

    # For each port, infer its outward direction from the nearest body cell.
    for idx in range(len(nodes)):
        ports = node_ports[idx]
        body = node_body_cells[idx]
        if not body or not ports:
            continue

        body_set = set(body)
        # Fast lookup for body bounding box fallback.
        rmin = min(r for r, _ in body)
        rmax = max(r for r, _ in body)
        cmin = min(c for _, c in body)
        cmax = max(c, c for c in (cc for _, cc in body))

        new_ports = []
        for r, c in ports:
            dirs = []

            # Direct opposite of adjacent body cells.
            if inb(r + 1, c) and (r + 1, c) in body_set:
                dirs.append((-1, 0))  # body below -> port points up
            if inb(r - 1, c) and (r - 1, c) in body_set:
                dirs.append((1, 0))   # body above -> port points down
            if inb(r, c + 1) and (r, c + 1) in body_set:
                dirs.append((0, -1))  # body right -> port points left
            if inb(r, c - 1) and (r, c - 1) in body_set:
                dirs.append((0, 1))   # body left -> port points right

            # Fallback by body bounding box.
            if not dirs:
                if r <= rmin:
                    dirs.append((-1, 0))
                elif r >= rmax:
                    dirs.append((1, 0))
                elif c <= cmin:
                    dirs.append((0, -1))
                elif c >= cmax:
                    dirs.append((0, 1))
                else:
                    dirs.append((1, 0))  # should not happen; pick downward

            # If multiple directions are inferred, keep all plausible ones.
            # In valid ARC grids this is usually just one direction.
            for d in dirs:
                new_ports.append((r, c, d))

        node_ports[idx] = new_ports

    # Build seed component from colors 2 and 4.
    seed_cells = []
    seed_owner = [[False] * W for _ in range(H)]

    if H and W:
        for sr in range(H):
            for sc in range(W):
                if seed_owner[sr][sc]:
                    continue
                if grid[sr][sc] in (2, 4):
                    q = deque([(sr, sc)])
                    seed_owner[sr][sc] = True
                    while q:
                        r, c = q.popleft()
                        seed_cells.append((r, c))
                        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                            nr, nc = r + dr, c + dc
                            if inb(nr, nc) and not seed_owner[nr][nc] and grid[nr][nc] in (2, 4):
                                seed_owner[nr][nc] = True
                                q.append((nr, nc))

    def paint(r, c):
        if inb(r, c):
            out[r][c] = 2

    def node_at(r, c):
        return owner[r][c]

    active = [False] * len(nodes)

    def activate(idx):
        if idx is None or idx < 0 or idx >= len(nodes) or active[idx]:
            return
        active[idx] = True
        for r, c in node_cells[idx]:
            paint(r, c)

    # Activate the seed.
    for r, c in seed_cells:
        paint(r, c)

    # Cast from seed endpoints along its long axis.
    if seed_cells:
        rs = [r for r, _ in seed_cells]
        cs = [c for _, c in seed_cells]
        vertical = (max(rs) - min(rs)) >= (max(cs) - min(cs))

        if vertical:
            top_r = min(rs)
            bot_r = max(rs)
            for r, c in seed_cells:
                if r == top_r:
                    for rr in range(r - 1, -1, -1):
                        idx = node_at(rr, c)
                        if idx != -1:
                            paint(rr, c)
                            activate(idx)
                            break
                        if seed_owner[rr][c]:
                            paint(rr, c)
                            break
                        paint(rr, c)
                if r == bot_r:
                    for rr in range(r + 1, H):
                        idx = node_at(rr, c)
                        if idx != -1:
                            paint(rr, c)
                            activate(idx)
                            break
                        if seed_owner[rr][c]:
                            paint(rr, c)
                            break
                        paint(rr, c)
        else:
            left_c = min(cs)
            right_c = max(cs)
            for r, c in seed_cells:
                if c == left_c:
                    for cc in range(c - 1, -1, -1):
                        idx = node_at(r, cc)
                        if idx != -1:
                            paint(r, cc)
                            activate(idx)
                            break
                        if seed_owner[r][cc]:
                            paint(r, cc)
                            break
                        paint(r, cc)
                if c == right_c:
                    for cc in range(c + 1, W):
                        idx = node_at(r, cc)
                        if idx != -1:
                            paint(r, cc)
                            activate(idx)
                            break
                        if seed_owner[r][cc]:
                            paint(r, cc)
                            break
                        paint(r, cc)

    # Propagate through activated nodes using their ports.
    q = deque(i for i, a in enumerate(active) if a)
    seen_queue = set(q)

    while q:
        idx = q.popleft()
        for r, c, (dr, dc) in node_ports[idx]:
            rr, cc = r + dr, c + dc
            while inb(rr, cc):
                hit = node_at(rr, cc)
                if hit != -1:
                    paint(rr, cc)
                    activate(hit)
                    if hit not in seen_queue:
                        seen_queue.add(hit)
                        q.append(hit)
                    break
                if seed_owner[rr][cc]:
                    paint(rr, cc)
                    break
                paint(rr, cc)
                rr += dr
                cc += dc

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    def is_border_color(c: int, r: int, col: int) -> bool:
        if r == 0 or r == H - 1:
            return grid[r][col] == c
        if col == 0 or col == W - 1:
            return grid[r][col] == c
        return False

    def border_dir(c: int, r: int, col: int) -> tuple[int, int] | None:
        if is_border_color(c, r, col):
            if r == 0 and (col != 0 and col != W - 1):
                return (0, 1)
            if r == H - 1 and (col != 0 and col != W - 1):
                return (0, -1)
            if col == 0 and (r != 0 and r != H - 1):
                return (1, 0)
            if col == W - 1 and (r != 0 and r != H - 1):
                return (-1, 0)
            return (0, 0)
        return None

    def solid_wall_color(r: int, col: int) -> int | None:
        for c in range(1, 10):
            if r == 0 or r == H - 1 or col == 0 or col == W - 1:
                continue
            if grid[r][col] == c:
                continue
            if (r == 0 or r == H - 1 or col == 0 or col == W - 1):
                continue
            if all(grid[rr][cc] == c for rr in range(H) for cc in range(W) if grid[rr][cc] != 0 and grid[rr][cc] != c):
                return c
        return None

    def background_color() -> int:
        counts = {}
        for row in grid:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        return max(counts, key=lambda k: (counts[k], k))

    bg = background_color()

    def wall_for_cell(r: int, col: int) -> int | None:
        # The background itself is not a wall.
        if grid[r][col] == bg:
            return None
        # Full-length solid background-color separators/walls.
        c = grid[r][col]
        if c == bg:
            return None
        if (r == 0 or r == H - 1 or col == 0 or col == W - 1):
            return None
        # If this colour forms one complete row or column, it is a wall.
        if all(grid[r][cc] == c for cc in range(W)):
            return c
        if all(grid[rr][col] == c for rr in range(H)):
            return c
        return None

    def is_wall_cell(r: int, col: int) -> bool:
        return wall_for_cell(r, col) is not None

    def is_movable_pixel(r: int, col: int) -> bool:
        if 0 <= r < H and 0 <= col < W:
            if grid[r][col] == bg:
                return False
            if is_wall_cell(r, col):
                return False
            # Border pixels that are not full wall rows/cols are treated as anchors, not movers.
            if r == 0 or r == H - 1 or col == 0 or col == W - 1:
                return False
        return False

    moves = {}
    for r in range(H):
        for c in range(W):
            if not is_movable_pixel(r, c):
                continue
            d = border_dir(grid[r][c], r, c)
            if d is None:
                continue
            moves[(r, c)] = d

    out = [row[:] for row in grid]

    # First clear movable pixels so old locations do not contaminate the result.
    for (r, c) in moves:
        out[r][c] = bg

    # Place each movable pixel one step toward its matching border colour.
    for (r, c), (dr, dc) in moves.items():
        nr = r + dr
        nc = c + dc
        if 0 <= nr < H and 0 <= nc < W:
            out[nr][nc] = grid[r][c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    H = len(grid)
    W = len(grid[0])

    def connected_color_cells(color: int):
        seen = set()
        cells = []
        for r in range(H):
            for c in range(W):
                if grid[r][c] == color and (r, c) not in seen:
                    q = deque([(r, c)])
                    seen.add((r, c))
                    while q:
                        rr, cc = q.popleft()
                        cells.append((rr, cc))
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                nr, nc = rr + dr, cc + dc
                                if 0 <= nr < H and 0 <= nc < W:
                                    if grid[nr][nc] == color and (nr, nc) not in seen:
                                        seen.add((nr, nc))
                                        q.append((nr, nc))
        return cells

    wall_colors = set()
    for r in range(H):
        if len(set(grid[r])) == 1:
            wall_colors.add(grid[r][0])
    for c in range(W):
        col = {grid[r][c] for r in range(H)}
        if len(col) == 1:
            wall_colors.add(next(iter(col)))

    bg = min(
        range(10),
        key=lambda x: (-sum(row.count(x) for row in grid), x)
    )

    out = [row[:] for row in grid]

    for color in range(1, 10):
        cells = connected_color_cells(color)
        if not cells:
            continue
        if color not in wall_colors:
            continue

        rs = [r for r, c in cells]
        cs = [c for r, c in cells]

        top_full = set(cells) == {(0, c) for c in range(W)} if min(rs) == max(rs) == 0 else False
        bottom_full = set(cells) == {(H - 1, c) for c in range(W)} if min(rs) == max(rs) == H - 1 else False
        left_full = set(cells) == {(r, 0) for r in range(H)} if min(cs) == max(cs) == 0 else False
        right_full = set(cells) == {(r, W - 1) for r in range(H)} if min(cs) == max(cs) == W - 1 else False

        if top_full or bottom_full or left_full or right_full:
            continue

        if len(cells) < 1:
            continue

        min_r, max_r = min(rs), max(rs)
        min_c, max_c = min(cs), max(cs)

        # The transformation used by the examples moves compact non-wall blobs
        # of a wall color toward the closest full wall line of that color.
        if min_r == 0 or max_r == H - 1 or min_c == 0 or max_c == W - 1:
            continue

        dist_top = min_r
        dist_bottom = (H - 1) - max_r
        dist_left = min_c
        dist_right = (W - 1) - max_c

        best = min(
            [(dist_top, 0, -1), (dist_bottom, 0, 1),
             (dist_left, -1, 0), (dist_right, 1, 0)],
            key=lambda x: (x[0], x[1] * 0, x[2] * 0)
        )
        dr, dc = best[1], best[2]

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                out[nr][nc] = color

    return out

import numpy as np

def _split_segments(rows):
    segs = []
    cur = None
    for r in rows:
        if r is not None:
            if cur is None:
                cur = [r]
            else:
                cur.append(r)
        else:
            if cur is not None:
                segs.append(cur)
                cur = None
    if cur is not None:
        segs.append(cur)
    return segs

def _blocks_from_grid(grid):
    n = len(grid)
    m = len(grid[0])

    # separator rows: all non-zero and at least one 5
    row_sep = [all(c != 0 for c in row) and any(c == 5 for c in row) for row in grid]
    # separator columns: all non-zero and at least one 5
    col_sep = [all(grid[r][c] != 0 for r in range(n)) and any(grid[r][c] == 5 for r in range(n))
               for c in range(m)]

    row_segs = _split_segments([row if not row_sep[i] else None for i, row in enumerate(grid)])
    col_segs = _split_segments([[grid[r][c] for r in range(n)] if not col_sep[c] else None
                                for c in range(m)])

    blocks = []
    for rb in row_segs:
        if len(rb) < 3:
            continue
        rows = []
        for cb in col_segs:
            if len(cb) < 3:
                continue
            rows.append([[cb[r][i] for i in range(3, len(cb) - 3)] for r in range(3, len(rb) - 3)])
        blocks.append(rows)
    return blocks

def _pattern_id(pat):
    s = set()
    for row in pat:
        for v in row:
            if v != 0:
                s.add(v)
    return tuple(sorted(s))

def _pattern_eq(a, b):
    h, w = len(a), len(a[0])
    return all(a[i][j] == b[i][j] for i in range(h) for j in range(w))

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the marker row: last row containing a color > 5 and no 5.
    marker_row = None
    for r in range(H - 1, -1, -1):
        row = g[r]
        if (row > 5).any() and (row == 5).sum() == 0:
            marker_row = r
            break
    if marker_row is None:
        marker_row = H - 1

    # Non-5 block grid (separators are rows/cols made of 5/other nonzero lines)
    row_sep = [(g[r] != 0).all() and (g[r] == 5).any() for r in range(H)]
    col_sep = [(g[:, c] != 0).all() and (g[:, c] == 5).any() for c in range(W)]

    row_segs = _split_segments([g[r] if not row_sep[r] else None for r in range(H)])
    col_segs = _split_segments([g[:, c] if not col_sep[c] else None for c in range(W)])

    # Keep only large interior blocks (remove marker/edge fragments)
    blocks = []
    for rb in row_segs:
        if len(rb) < 5:
            continue
        block_row = []
        for cb in col_segs:
            if len(cb) < 5:
                continue
            pat = cb[3:-3, 3:-3]
            if pat.size == 0:
                continue
            block_row.append(pat)
        if block_row:
            blocks.append(block_row)

    if not blocks or not blocks[0]:
        return []

    # Marker columns: inside the three main column bands
    marker_cols = []
    for c in range(W):
        if g[marker_row, c] > 5:
            marker_cols.append(c)
    # Map marker columns to column band indices
    col_band_edges = []
    start = 0
    for c, is_sep in enumerate(col_sep):
        if is_sep:
            col_band_edges.append((start, c - 1))
            start = c + 1
    col_band_edges.append((start, W - 1))

    def band_of(x):
        for i, (a, b) in enumerate(col_band_edges):
            if a <= x <= b:
                return i
        return None

    marker_bands = [band_of(c) for c in marker_cols]
    marker_bands = [i for i in marker_bands if i is not None]

    # Assign marker colors to the first three pattern IDs.
    patterns = []
    pattern_ids = []
    for brow in blocks:
        for pat in brow:
            pid = tuple(sorted({int(v) for v in pat.flatten() if v != 0}))
            if pid not in pattern_ids:
                pattern_ids.append(pid)
                patterns.append(pat)

    color_for_pid = {}
    if len(marker_bands) >= len(pattern_ids):
        for idx, pid in enumerate(pattern_ids):
            color_for_pid[pid] = int(g[marker_row, marker_cols[idx]])
    else:
        # Fallback: use any marker colors in order
        for idx, pid in enumerate(pattern_ids):
            color_for_pid[pid] = int(g[marker_row, marker_cols[min(idx, len(marker_cols) - 1)]])

    # Reconstruct output size from blocks: block height = pattern side * (#pattern rows)
    pat_h, pat_w = len(patterns[0]), len(patterns[0][0])
    macro_rows = len(blocks)
    macro_cols = len(blocks[0])

    # The output macro grid is pattern_size x pattern_size if examples use 3 or 5;
    # for these puzzles it matches len(patterns[0]).
    out_macro = pat_h
    out = np.zeros((out_macro * pat_h, out_macro * pat_w), dtype=int)

    # Determine which macro cell gets which pattern by locating each input block
    # in the macro grid: row = its row band, col = its column band.
    for br, brow in enumerate(blocks):
        for bc, pat in enumerate(brow):
            pid = tuple(sorted({int(v) for v in pat.flatten() if v != 0}))
            col = color_for_pid.get(pid, 0)
            if col == 0:
                continue
            r0 = br * pat_h
            c0 = bc * pat_w
            for i in range(pat_h):
                for j in range(pat_w):
                    if pat[i, j] != 0:
                        out[r0 + i, c0 + j] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    def longest_line(color: int) -> int:
        best = 0
        for i in range(h):
            cur = 0
            for j in range(w):
                if g[i, j] == color:
                    cur += 1
                    if cur > best:
                        best = cur
                else:
                    cur = 0
        for j in range(w):
            cur = 0
            for i in range(h):
                if g[i, j] == color:
                    cur += 1
                    if cur > best:
                        best = cur
                else:
                    cur = 0
        return best

    colors = set(g.ravel().tolist()) - {0}
    frame_color = max(colors, key=lambda c: (longest_line(c), c))

    mask = (g == frame_color)
    rows = np.any(mask, axis=1)
    cols = np.any(mask, axis=0)

    rmin = int(np.argmax(rows))
    rmax = int(h - 1 - np.argmax(rows[::-1]))
    cmin = int(np.argmax(cols))
    cmax = int(w - 1 - np.argmax(cols[::-1]))

    out = g[rmin + 1:rmax, cmin + 1:cmax].copy()
    out[out != 0] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(out)
    # The puzzle grids use a 30x30 layout with horizontal mirror r -> 31 - r.
    for r in range(h):
        mr = 31 - r
        if 0 <= mr < h:
            for c in range(len(out[r])):
                if out[r][c] == 8 and out[mr][c] != 8:
                    out[r][c] = out[mr][c]
    # Resolve mirrored 8s inside the hidden rectangle.
    changed = True
    while changed:
        changed = False
        for r in range(h):
            mr = 31 - r
            if 0 <= mr < h:
                for c in range(len(out[r])):
                    if out[r][c] == 8 and out[mr][c] != 8:
                        out[r][c] = out[mr][c]
                        changed = True
                    elif out[mr][c] == 8 and out[r][c] != 8:
                        out[mr][c] = out[r][c]
                        changed = True

    # Extract the rectangular block originally filled with 8s.
    mask = [[cell == 8 for cell in row] for row in grid]
    rows = [r for r in range(h) if any(mask[r])]
    cols = [c for c in range(len(grid[0])) if any(mask[r][c] for r in rows)]
    r0, r1 = min(rows), max(rows)
    c0, c1 = min(cols), max(cols)

    return [out[r][c0:c1 + 1] for r in range(r0, r1 + 1)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    # Make a mutable copy
    out = [row[:] for row in grid]

    # For every horizontal 777 segment, paint a vertical 666 line
    # through the center column on rows r-1, r, r+1.
    for r in range(h):
        c = 0
        while c < w:
            if (
                grid[r][c] == 7
                and c + 2 < w
                and grid[r][c + 1] == 7
                and grid[r][c + 2] == 7
            ):
                mid = c + 1
                for rr in (r - 1, r, r + 1):
                    if 0 <= rr < h:
                        out[rr][mid] = 6
                c += 3
            else:
                c += 1

    # Determine which even rows keep their 3/8 endpoints.
    # A row keeps endpoints iff both left and right border cells are 8 in input.
    keep = [
        i % 2 == 0 and 0 <= i < h and grid[i][0] == 8 and grid[i][-1] == 8
        for i in range(h)
    ]

    # Recolour outer border:
    # - keep rows become 3 at both outer ends
    # - non-keep rows become 8 at both outer ends
    for i in range(h):
        if i % 2 == 0 and i > 0 and i < h - 1:
            if keep[i]:
                out[i][0] = 3
                out[i][w - 1] = 3
            else:
                out[i][0] = 8
                out[i][w - 1] = 8

    # Special-case first and last rows:
    # - if the top row was a normal 3/8 row, make it all 8 except preserved 0s and new 6s
    if h > 0 and grid[0][0] == 3 and grid[0][-1] == 3:
        for c in range(w):
            if grid[0][c] in (8, 3):
                out[0][c] = 8

    # - if the bottom row is not a normal 3/8 row, turn its 8-cells
    #   adjacent to preserved 0s, plus the right border, into 3
    if h > 0 and not (grid[h - 1][0] == 3 and grid[h - 1][-1] == 3):
        for c in range(w):
            if grid[h - 1][c] == 8:
                left0 = c > 0 and grid[h - 1][c - 1] == 0
                right0 = c < w - 1 and grid[h - 1][c + 1] == 0
                if left0 or right0 or c == w - 1:
                    out[h - 1][c] = 3

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # 1) Every horizontal 777 becomes an 868 on its own row and leaves
    #    a vertical 6 in the adjacent rows above and below.
    for r in range(h):
        c = 0
        while c < w:
            if (
                grid[r][c] == 7
                and c + 2 < w
                and grid[r][c + 1] == 7
                and grid[r][c + 2] == 7
            ):
                mid = c + 1
                out[r][c] = 8
                out[r][c + 2] = 8
                out[r][mid] = 6

                for rr in (r - 1, r + 1):
                    if 0 <= rr < h:
                        out[rr][mid] = 6

                c += 3
            else:
                c += 1

    # 2) Re-color some cells on even rows to 3.
    #
    # Interior even rows:
    #   - if the input left border cell is 3, paint the first two cells 3;
    #   - if the input right border cell is 3, paint the last two cells 3.
    for r in range(1, h - 1, 2):
        if r < h:
            if grid[r][0] == 3:
                if w >= 2:
                    out[r][0] = 3
                    out[r][1] = 3
            if grid[r][w - 1] == 3:
                if w >= 2:
                    out[r][w - 2] = 3
                    out[r][w - 1] = 3

    # Top row, if it originally had 3-border:
    if h > 0 and grid[0][0] == 3 and grid[0][w - 1] == 3:
        for c in range(w):
            if grid[0][c] in (3, 8):
                out[0][c] = 8

    # Bottom row:
    if h > 0:
        r = h - 1
        # If it is a normal 3-border row, make both ends 3.
        if grid[r][0] == 3 and grid[r][w - 1] == 3:
            out[r][0] = 3
            out[r][w - 1] = 3
        else:
            # For every 8-cell next to a 0, make it 3.
            for c in range(w):
                if grid[r][c] == 8:
                    if (c > 0 and grid[r][c - 1] == 0) or (
                        c + 1 < w and grid[r][c + 1] == 0
                    ):
                        out[r][c] = 3
            # If the row has any zero, also make the right border 3.
            if 0 in grid[r]:
                out[r][w - 1] = 3

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

    H = len(grid)
    W = len(grid[0]) if H else 0

    # Find the rectangular 0-panel: its bounding box is the output size.
    zeros = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == 0]
    if not zeros:
        return [[0 for _ in range(W)] for _ in range(H)]

    rmin = min(r for r, _ in zeros)
    rmax = max(r for r, _ in zeros)
    cmin = min(c for _, c in zeros)
    cmax = max(c for _, c in zeros)

    out_h = rmax - rmin + 1
    out_w = cmax - cmin + 1
    out = [[0] * out_w for _ in range(out_h)]

    # Markers are the non-zero cells inside that 0-panel.
    markers = []
    marker_coords_by_color = {}
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            v = grid[r][c]
            if v != 0:
                markers.append((r, c, v))
                marker_coords_by_color.setdefault(v, set()).add((r, c))

    if not markers:
        return out

    def count_outside_components(color: int, marker_coords: set) -> int:
        visited = set()
        count = 0

        for sr in range(H):
            for sc in range(W):
                if grid[sr][sc] != color or (sr, sc) in visited:
                    continue

                q = deque([(sr, sc)])
                visited.add((sr, sc))
                contains_marker = False

                while q:
                    r, c = q.popleft()
                    if (r, c) in marker_coords:
                        contains_marker = True

                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if (
                                0 <= nr < H
                                and 0 <= nc < W
                                and grid[nr][nc] == color
                                and (nr, nc) not in visited
                            ):
                                visited.add((nr, nc))
                                q.append((nr, nc))

                if not contains_marker:
                    count += 1

        return count

    counts_by_color = {
        color: count_outside_components(color, coords)
        for color, coords in marker_coords_by_color.items()
    }

    # For each marker row, write that many colored dots, spaced by one empty cell,
    # starting at the marker's column inside the panel.
    for r, c, v in markers:
        pr = r - rmin
        pc = c - cmin
        n = counts_by_color[v]
        for i in range(n):
            col = pc + 2 * i
            if 0 <= col < out_w:
                out[pr][col] = v

    return out

