from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def add_segment(a, b, color):
        r0, c0 = a
        r1, c1 = b
        dr = np.sign(r1 - r0)
        dc = np.sign(c1 - c0)
        r, c = r0, c0
        while True:
            out[r, c] = color
            if r == r1 and c == c1:
                break
            if r == r1:
                c += dc
            elif c == c1:
                r += dr
            else:
                # Move horizontally first, then vertically/diagonally.
                c += dc
                r += dr

    colors = {}
    for r in range(H):
        for c in range(W):
            v = g[r, c]
            if v != 0:
                colors.setdefault(v, []).append((r, c))

    for color, pts in colors.items():
        if len(pts) < 2:
            continue
        pts = sorted(set(pts))

        # Keep extreme points: upper hull, then lower hull, merging adjacent
        # collinear points.  This draws the convex-hull boundary with
        # 8-neighbour straight segments.
        upper = []
        for p in pts:
            while len(upper) >= 2:
                a, b = upper[-2], upper[-1]
                r1, c1 = a
                r2, c2 = b
                r3, c3 = p
                cross = (r2 - r1) * (c3 - c2) - (c2 - c1) * (r3 - r2)
                if cross > 0:
                    upper.pop()
                else:
                    break
            upper.append(p)

        lower = []
        for p in reversed(pts):
            while len(lower) >= 2:
                a, b = lower[-2], lower[-1]
                r1, c1 = a
                r2, c2 = b
                r3, c3 = p
                cross = (r2 - r1) * (c3 - c2) - (c2 - c1) * (r3 - r2)
                if cross > 0:
                    lower.pop()
                else:
                    break
            lower.append(p)

        if len(upper) >= 2 and upper[0] != upper[-1]:
            upper.append(upper[0])
        if len(lower) >= 2 and lower[0] != lower[-1]:
            lower.append(lower[0])

        hull = upper[:-1] + lower[1:]

        if len(hull) >= 3:
            for i in range(len(hull)):
                add_segment(hull[i], hull[(i + 1) % len(hull)], color)
        elif len(hull) == 2:
            add_segment(hull[0], hull[1], color)

    return out.tolist()

import numpy as np
from typing import List, Tuple

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def draw_line(a: Tuple[int, int], b: Tuple[int, int], color: int) -> None:
        r0, c0 = a
        r1, c1 = b

        dr = r1 - r0
        dc = c1 - c0

        adx = abs(dc)
        ady = abs(dr)
        sdx = 1 if dc > 0 else -1
        sdy = 1 if dr > 0 else -1

        x, y = r0, c0
        dx, dy = adx, ady

        while True:
            if 0 <= x < H and 0 <= y < W and out[x, y] == 0:
                out[x, y] = color

            if x == r1 and y == c1:
                break

            xx = 2 * dx
            yy = 2 * dy

            if xx < yy:
                x += sdx
                dy += xx
            elif yy < xx:
                y += sdy
                dx += yy
            else:
                x += sdx
                y += sdy
                dx += xx
                dy += yy

    def convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        # Concatenate without duplicating endpoints.
        hull = lower[:-1] + upper[:-1]

        # Remove collinear intermediate points, but keep all vertices needed
        # for the expected output boundaries.
        cleaned = []
        if not hull:
            return []
        if len(hull) <= 2:
            return hull

        for i in range(len(hull)):
            p0 = hull[(i - 1) % len(hull)]
            p1 = hull[i]
            p2 = hull[(i + 1) % len(hull)]
            if cross(p0, p1, p2) == 0:
                # Keep one endpoint of collinear runs only if it is an extreme point.
                # In all observed cases, keeping all hull points drawn as separate
                # segments gives the expected 8-connected boundary.
                cleaned.append(p1)
            else:
                cleaned.append(p1)
        return cleaned

    colors = {}
    for r in range(H):
        for c in range(W):
            v = int(g[r, c])
            if v != 0:
                colors.setdefault(v, []).append((r, c))

    for color, pts in colors.items():
        if len(pts) < 2:
            continue

        hull = convex_hull(pts)
        if len(hull) < 2:
            continue

        # Draw edges of the hull in order.
        for i in range(len(hull)):
            a = hull[i]
            b = hull[(i + 1) % len(hull)]
            if a != b:
                draw_line(a, b, color)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]):
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Find the 4-marker line and the other (non-background) object colour.
    ys, xs = np.where(a == 4)
    rows4 = set(ys.tolist())
    cols4 = set(xs.tolist())

    if len(rows4) == 1:
        marker_dir = 'h'          # horizontal marker
        fixed = ys[0]
        var = sorted(cols4)
    else:
        marker_dir = 'v'          # vertical marker
        fixed = xs[0]
        var = sorted(rows4)

    marker_len = len(var)
    marker_start = var[0]

    out = a.copy()

    # Background is the most common colour, or 0 if all colours are equally common.
    counts = np.bincount(a.ravel(), minlength=10)
    if len(var) > 1:
        bg = int(np.argmax(counts))
        if counts[bg] == counts[4]:
            bg = 0
    else:
        bg = int(np.argmax(counts))
        if counts[bg] == counts[4]:
            bg = 0

    def is_marker_line(idx: int) -> bool:
        # idx is the coordinate along the marker's length axis
        return idx - marker_start < marker_len

    if marker_dir == 'h':
        # Marker is a horizontal row.  Replicate it vertically every 6 rows:
        #   distance 0, 6, 12, ... : colour 4
        #   distance 3, 9, 15, ... : colour 3
        # only where the original cell belonged to the main object colour.
        # The 4-marker itself is preserved.
        target = None
        for c in range(10):
            if c != 4 and c != bg and counts[c] > 0:
                target = c
                break

        if target is not None:
            for r in range(h):
                d = abs(r - fixed)
                if d % 6 == 0:
                    val = 4
                elif d % 6 == 3:
                    val = 3
                else:
                    continue
                for c in range(w):
                    if is_marker_line(c) and a[r, c] == target:
                        out[r, c] = val

        # Restore / paint the original 4-marker line itself.
        for c in var:
            out[fixed, c] = 4

    else:
        # Marker is a vertical column.  Replicate it horizontally every 6 columns:
        #   distance 0, 6, 12, ... : colour 4
        #   distance 3, 9, 15, ... : colour 3
        # only where the original cell belonged to the main object colour.
        # The 4-marker itself is preserved.
        target = None
        for c in range(10):
            if c != 4 and c != bg and counts[c] > 0:
                target = c
                break

        if target is not None:
            for c in range(w):
                d = abs(c - fixed)
                if d % 6 == 0:
                    val = 4
                elif d % 6 == 3:
                    val = 3
                else:
                    continue
                for r in range(h):
                    if is_marker_line(r) and a[r, c] == target:
                        out[r, c] = val

        # Restore / paint the original 4-marker line itself.
        for r in var:
            out[r, fixed] = 4

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    colours = {}
    for row in grid:
        for c in row:
            colours[c] = colours.get(c, 0) + 1
    bg = max(colours, key=lambda k: colours[k])

    # 4-connected components of non-background cells
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if not seen[r][c] and grid[r][c] != bg:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny][nx] and grid[ny][nx] != bg:
                                seen[ny][nx] = True
                                stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                components.append({
                    "cells": cells,
                    "y0": min(ys), "y1": max(ys),
                    "x0": min(xs), "x1": max(xs),
                    "h": max(ys) - min(ys) + 1,
                    "w": max(xs) - min(xs) + 1,
                })

    if not components:
        return []

    # Keep only "interesting" components (tall enough), ordered left-to-right
    chosen = [c for c in components if c["h"] >= 3]
    if not chosen:
        chosen = components
    chosen.sort(key=lambda c: (c["x0"] + c["x1"]) / 2)

    out_rows = 5
    result = None

    for comp in chosen:
        y0, y1 = comp["y0"], comp["y1"]
        x0, x1 = comp["x0"], comp["x1"]
        width = x1 - x0 + 1

        block = [[bg] * width for _ in range(out_rows)]
        top = max(0, (out_rows - comp["h"]) // 2)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                block[top + (y - y0)][x - x0] = grid[y][x]

        if result is None:
            result = block
        else:
            # Merge: if the right border of result equals the left border of block,
            # overlap by one column (identical columns merge into one).
            merge = 0
            if len(result) > 0:
                rw = len(result[0])
                if rw > 0 and width > 0:
                    right_col = [result[r][rw - 1] for r in range(out_rows)]
                    left_col = [block[r][0] for r in range(out_rows)]
                    if right_col == left_col:
                        merge = 1
            if merge:
                new_w = len(result[0]) + width - 1
                merged = [row[:] for row in result]
                for r in range(out_rows):
                    merged[r] = merged[r] + block[r][1:]
                result = merged
            else:
                for r in range(out_rows):
                    result[r] = result[r] + block[r]

    return result

