from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def non8_cells(sub):
        return [(r, c) for r in range(sub.shape[0]) for c in range(sub.shape[1]) if sub[r, c] != 8]

    # Collect all maximal straight beams of non-8, non-1 cells.
    beams = []
    seen = set()

    def add_beam_cells(r, c, dr, dc):
        while True:
            r2 = r + dr
            c2 = c + dc
            if 0 <= r2 < H and 0 <= c2 < W and g[r2, c2] not in (8, 1):
                r, c = r2, c2
            else:
                break
        key = (r, c, dr, dc)
        if key in seen:
            return
        seen.add(key)
        beams.append((r, c, dr, dc))

    for r in range(H):
        for c in range(W):
            if g[r, c] in (8, 1):
                continue
            if r == 0 or g[r - 1, c] in (8, 1):
                add_beam_cells(r, c, 1, 0)
            if c == 0 or g[r, c - 1] in (8, 1):
                add_beam_cells(r, c, 0, 1)

    # For each beam, see if it touches a 1-cell immediately before it.
    candidates = []
    for (r, c, dr, dc) in beams:
        br, bc = r - dr, c - dc
        if not (0 <= br < H and 0 <= bc < W) or g[br, bc] != 1:
            continue

        # Width: if horizontal beam (dc != 0), number of consecutive rows at the first column;
        # if vertical beam (dr != 0), number of consecutive columns at the first row.
        width = 0
        if dc != 0:
            while (0 <= r - width < H and 0 <= c < W and
                   g[r - width, c] not in (8, 1) and
                   g[br - width, bc] == 1):
                width += 1
        else:
            while (0 <= r < H and 0 <= c - width < W and
                   g[r, c - width] not in (8, 1) and
                   g[br, bc - width] == 1):
                width += 1
        if width <= 0:
            continue

        # The beam must be adjacent to 1 cells for its whole width on the body side.
        body_ok = True
        for t in range(width):
            if dc != 0:
                rr, cc = r - t, c
            else:
                rr, cc = r, c - t
            if rr - dr < 0 or rr - dr >= H or cc - dc < 0 or cc - dc >= W:
                body_ok = False
                break
            if g[rr - dr, cc - dc] != 1:
                body_ok = False
                break
        if not body_ok:
            continue

        # Check that every cell in this beam line belongs to non-8/non-1.
        ok = True
        rr, cc = r, c
        while True:
            if g[rr, cc] in (8, 1):
                ok = False
                break
            rr += dr
            cc += dc
            if not (0 <= rr < H and 0 <= cc < W) or g[rr, cc] in (8, 1):
                break
        if not ok:
            continue

        # If this beam already reaches a grid boundary, do not extend it.
        rr, cc = r, c
        reaches = False
        while 0 <= rr < H and 0 <= cc < W:
            if g[rr, cc] in (8, 1):
                break
            if rr == 0 or rr == H - 1 or cc == 0 or cc == W - 1:
                reaches = True
                break
            rr += dr
            cc += dc
        if reaches:
            continue

        candidates.append((r, c, dr, dc, width))

    # Extend every qualifying beam by repeating its cross-sectional pattern.
    for (r, c, dr, dc, width) in candidates:
        # First cross-section immediately adjacent to the 1-body.
        pattern = []
        for t in range(width):
            if dc != 0:
                rr, cc = r - t, c
            else:
                rr, cc = r, c - t
            pattern.append(g[rr, cc])

        nr, nc = r + dr, c + dc
        i = 1
        while 0 <= nr < H and 0 <= nc < W:
            for t in range(width):
                if dc != 0:
                    rr, cc = nr - t, nc
                else:
                    rr, cc = nr, nc - t
                # Only write into background so we do not corrupt other objects.
                if g[rr, cc] == 8:
                    out[rr, cc] = pattern[t]
            nr += dr
            nc += dc
            i += 1

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    out = [list(r) for r in grid]

    def is_bg(r, c):
        return grid[r][c] == 8

    def is_cross(r, c):
        return grid[r][c] == 1

    def inb(r, c):
        return 0 <= r < H and 0 <= c < W

    # Find vertical beams: maximal vertical runs of non-8, non-1 cells
    for c in range(W):
        r = 0
        while r < H:
            if grid[r][c] not in (8, 1):
                r2 = r
                while r2 + 1 < H and grid[r2 + 1][c] not in (8, 1):
                    r2 += 1
                length = r2 - r + 1
                # Determine period
                vals = [grid[i][c] for i in range(r, r2 + 1)]
                period = 1
                if length >= 2:
                    for p in range(1, length):
                        if all(vals[i] == vals[i % p] for i in range(length)):
                            period = p
                            break
                # Determine direction to extend
                up_blocked = (r == 0 or is_cross(r - 1, c) or grid[r - 1][c] not in (8, 1))
                dn_blocked = (r2 == H - 1 or is_cross(r2 + 1, c) or grid[r2 + 1][c] not in (8, 1))

                if not up_blocked:
                    # Extend upward
                    for i in range(1, r):
                        if is_bg(r - i, c):
                            idx = (r - i - r) % period  # negative modulo
                            out[r - i][c] = vals[idx]
                        else:
                            # Hit a non-8, non-1 cell that's not part of this beam
                            # Overwrite it (beam extension overwrites)
                            idx = (r - i - r) % period
                            out[r - i][c] = vals[idx]
                if not dn_blocked:
                    for i in range(1, H - r2):
                        rr = r2 + i
                        if rr >= H:
                            break
                        idx = i % period
                        out[rr][c] = vals[idx]
                r = r2 + 1
            else:
                r += 1

    # Find horizontal beams: maximal horizontal runs of non-8, non-1 cells
    for r in range(H):
        c = 0
        while c < W:
            if grid[r][c] not in (8, 1):
                c2 = c
                while c2 + 1 < W and grid[r][c2 + 1] not in (8, 1):
                    c2 += 1
                length = c2 - c + 1
                vals = [grid[r][j] for j in range(c, c2 + 1)]
                period = 1
                if length >= 2:
                    for p in range(1, length):
                        if all(vals[i] == vals[i % p] for i in range(length)):
                            period = p
                            break
                left_blocked = (c == 0 or is_cross(r, c - 1) or grid[r][c - 1] not in (8, 1))
                right_blocked = (c2 == W - 1 or is_cross(r, c2 + 1) or grid[r][c2 + 1] not in (8, 1))

                if not left_blocked:
                    for i in range(1, c):
                        cc = c - i
                        if cc < 0:
                            break
                        idx = (-i) % period
                        out[r][cc] = vals[idx]
                if not right_blocked:
                    for i in range(1, W - c2):
                        cc = c2 + i
                        if cc >= W:
                            break
                        idx = i % period
                        out[r][cc] = vals[idx]
                c = c2 + 1
            else:
                c += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
