    def valid(pos):
        r, c = pos
        if r < 0 or c < 0 or r + size >= H or c + size >= W:
            return False
        return True

    def fits_1(pos):
        r, c = pos
        return np.all(g[r:r + size, c:c + size] == 1)

    def fits_2(pos):
        r, c = pos
        return np.all(g[r:r + size, c:c + size] == 2)

    # If the 2-square is a possible destination, choose it directly.
    # This covers examples where the 0-square moves onto the 2-square.
    if valid(t_pos) and fits_2(t_pos):
        best = t_pos
    else:
        # Otherwise move the 0-square through the 1-region until it is blocked.
        # The final resting place is the last 1-valid square before the first step
        # that cannot be fully covered by 1s.
        seen = {z_pos}
        q = deque([z_pos])
        best = None
        while q:
            cur = q.popleft()
            for nb in neighbors(cur, size):
                if nb in seen:
                    continue
                seen.add(nb)
                if valid(nb) and fits_1(nb):
                    best = nb
                    q.append(nb)
                # If nb is invalid or not all 1s, it is just a boundary block.
        if best is None:
            # Fallback: should not happen for intended inputs.
            best = z_pos

    out = g.copy()

    # Remove original 0 square by filling it with 1.
    r, c = z_pos
    out[r:r + size, c:c + size] = 1

    # Place the 0 square at the chosen destination.
    r, c = best
    out[r:r + size, c:c + size] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The moving object is the solid square of 0s.
    zero_cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 0]
    if not zero_cells:
        return [row[:] for row in grid]

    sz = int(round(len(zero_cells) ** 0.5))
    z0 = min(zero_cells)
    z1 = max(zero_cells)
    assert z1[0] - z0[0] + 1 == sz and z1[1] - z0[1] + 1 == sz

    # The 2-square, if present, is the preferred destination.
    two_cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 2]
    if two_cells:
        t0 = min(two_cells)
        t1 = max(two_cells)
        assert t1[0] - t0[0] + 1 == sz and t1[1] - t0[1] + 1 == sz
    else:
        t0 = None

    def in_bounds(pos):
        r, c = pos
        return 0 <= r and 0 <= c and r + sz < H and c + sz < W

    def allowed_move_to(pos):
        # The hole may move through non-background cells (1, 2, and its own 0s).
        # It may not move into background 3.
        r, c = pos
        block = g[r:r + sz, c:c + sz]
        return np.all(block != 3)

    def step_candidates(pos):
        r, c = pos
        seen = set()
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                np_ = (r + dr, c + dc)
                if np_ in seen:
                    continue
                seen.add(np_)
                if in_bounds(np_) and allowed_move_to(np_):
                    yield np_

    def center(pos):
        r, c = pos
        return r + (sz - 1) / 2.0, c + (sz - 1) / 2.0

    def target_center():
        if t0 is not None:
            return center(t0)
        # No 2: fall back to moving toward the center of the non-background object.
        mask = g != 3
        ys, xs = np.nonzero(mask)
        if len(ys) == 0:
            return center(z0)
        return float(np.mean(ys)), float(np.mean(xs))

    def best_score(pos, tgt):
        cr, cc = center(pos)
        tr, tc = tgt
        dr = tr - cr
        dc = tc - cc
        length = (dr * dr + dc * dc) ** 0.5
        if length == 0:
            return 0.0
        # Directional progress toward the target, with a small preference
        # for positions that are closer to the target when progress is tied.
        progress = (dr * dr + dc * dc) ** 0.5  # placeholder not used
        dot = (dr * dr + dc * dc) ** 0.5  # placeholder not used
        # Better: score by dot product of displacement from start to pos with target vector.
        sr, sc = center(z0)
        vr = cr - sr
        vc = cc - sc
        tvec_r = tr - sr
        tvec_c = tc - sc
        tnorm = (tvec_r * tvec_r + tvec_c * tvec_c) ** 0.5
        if tnorm == 0:
            score = 0.0
        else:
            score = (vr * tvec_r + vc * tvec_c) / tnorm
        dist_to_target = (cr - tr) * (cr - tr) + (cc - tc) * (cc - tc)
        return score * 1000.0 - dist_to_target * 0.001

    def choose_destination():
        # If the 2-square is directly reachable by a legal sliding path, use it.
        if t0 is not None:
            # BFS from start to 2 through legal positions.
            parent = {z0: None}
            q = deque([z0])
            while q:
                cur = q.popleft()
                if cur == t0:
                    return t0
                for nb in step_candidates(cur):
                    if nb not in parent:
                        parent[nb] = cur
                        q.append(nb)

        tgt = target_center()

        # Among all reachable positions, choose the one with maximum progress
        # toward the target; small tie-breaker toward the target itself.
        reachable = {z0: 0}
        q = deque([z0])
        best = z0
        best_score_val = best_score(z0, tgt)
        while q:
            cur = q.popleft()
            for nb in step_candidates(cur):
                if nb in reachable:
                    continue
                reachable[nb] = reachable[cur] + 1
                s = best_score(nb, tgt)
                if s > best_score_val + 1e-12:
                    best_score_val = s
                    best = nb
                q.append(nb)
        return best

    dest = choose_destination()

    out = g.copy()

    # The original hole is filled with 1.
    r, c = z0
    out[r:r + sz, c:c + sz] = 1

    # The destination becomes the hole.
    r, c = dest
    out[r:r + sz, c:c + sz] = 0

    return out.tolist()

import sys
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalize input to a 2D list of ints.
    if not grid:
        return []
    if all(isinstance(row, str) for row in grid):
        g = [[int(ch) for ch in row] for row in grid]
    else:
        g = [[int(v) for v in row] for row in grid]

    h = len(g)
    w = len(g[0]) if h else 0

    # Find the vertical separator line:
    # the longest vertical contiguous run of the same non-zero colour.
    best = None  # (length, count_in_column, -abs(offset_from_centre), start, end, col, color)
    for c in range(w):
        r = 0
        while r < h:
            v = g[r][c]
            if v == 0:
                r += 1
                continue
            r0 = r
            while r < h and g[r][c] == v:
                r += 1
            r1 = r - 1
            length = r1 - r0 + 1
            col_count = sum(1 for rr in range(h) if g[rr][c] == v)
            centre = (w - 1) / 2.0
            tie = -abs(c - centre)
            key = (length, col_count, tie, r0, r1, c, v)
            if best is None or key > best:
                best = key

    if best is None:
        return g

    _, _, _, line_start, line_end, line_col, line_color = best

    # Determine which side of the line contains the source bars.
    left_nonzero = 0
    right_nonzero = 0
    for r in range(h):
        if r < line_start or r > line_end:
            continue
        for c in range(w):
            if c == line_col:
                continue
            if g[r][c] != 0:
                if c < line_col:
                    left_nonzero += 1
                else:
                    right_nonzero += 1

    if left_nonzero == 0 and right_nonzero == 0:
        return g

    if left_nonzero >= right_nonzero:
        source_side = 'left'
        target_side = 'right'
    else:
        source_side = 'right'
        target_side = 'left'

    out = [row[:] for row in g]

    for r in range(line_start, line_end + 1):
        # Collect source bars in this row: maximal contiguous runs of a
        # single non-zero colour on the source side.
        bars = []
        if source_side == 'left':
            c = line_col - 1
            while c >= 0:
                v = g[r][c]
                if v == 0:
                    c -= 1
                    continue
                c1 = c
                while c >= 0 and g[r][c] == v:
                    c -= 1
                c0 = c + 1
                length = c1 - c0 + 1
                dist = line_col - c1
                bars.append((dist, v, length))
            c += 1
        else:
            c = line_col + 1
            while c < w:
                v = g[r][c]
                if v == 0:
                    c += 1
                    continue
                c0 = c
                while c < w and g[r][c] == v:
                    c += 1
                c1 = c - 1
                length = c1 - c0 + 1
                dist = c0 - line_col
                bars.append((dist, v, length))

        if not bars:
            continue

        # Closer bars to the line have priority in conflicts.
        bars.sort(key=lambda x: x[0])

        if target_side == 'right':
            max_off = w - line_col - 1
            if max_off <= 0:
                continue
            chosen = [0] * (max_off + 1)
            for _, color, L in bars:
                off = 0
                while off <= max_off:
                    if chosen[off] == 0:
                        chosen[off] = color
                    off += L
            for off, color in enumerate(chosen):
                if color != 0:
                    out[r][line_col + 1 + off] = color
        else:
            max_off = line_col
            if max_off <= 0:
                continue
            chosen = [0] * (max_off + 1)
            for _, color, L in bars:
                off = 0
                while off <= max_off:
                    if chosen[off] == 0:
                        chosen[off] = color
                    off += L
            for off, color in enumerate(chosen):
                if color != 0:
                    out[r][line_col - 1 - off] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []
    if all(isinstance(row, str) for row in grid):
        g = [[int(ch) for ch in row] for row in grid]
    else:
        g = [[int(v) for v in row] for row in grid]

    h = len(g)
    w = len(g[0]) if h else 0

    # Find the vertical separator line: longest vertical run of same non-zero colour
    best = None  # (length, col, start_row, end_row, colour)
    for c in range(w):
        r = 0
        while r < h:
            v = g[r][c]
            if v == 0:
                r += 1
                continue
            r0 = r
            while r < h and g[r][c] == v:
                r += 1
            r1 = r - 1
            length = r1 - r0 + 1
            if best is None or length > best[0]:
                best = (length, c, r0, r1, v)

    if best is None:
        return g

    line_len, line_col, line_start, line_end, line_color = best

    # Determine which side has the source objects
    left_count = 0
    right_count = 0
    for r in range(line_start, line_end + 1):
        for c in range(line_col):
            if g[r][c] != 0:
                left_count += 1
        for c in range(line_col + 1, w):
            if g[r][c] != 0:
                right_count += 1

    source_left = (left_count >= right_count)

    out = [row[:] for row in g]

    for r in range(line_start, line_end + 1):
        # Collect bars on the source side: (distance_from_line, colour, length)
        bars = []
        if source_left:
            c = line_col - 1
            while c >= 0:
                v = g[r][c]
                if v == 0:
                    c -= 1
                    continue
                c1 = c
                while c >= 0 and g[r][c] == v:
                    c -= 1
                c0 = c + 1
                length = c1 - c0 + 1
                dist = line_col - c1
                bars.append((dist, v, length))
        else:
            c = line_col + 1
            while c < w:
                v = g[r][c]
                if v == 0:
                    c += 1
                    continue
                c0 = c
                while c < w and g[r][c] == v:
                    c += 1
                c1 = c - 1
                length = c1 - c0 + 1
                dist = c0 - line_col
                bars.append((dist, v, length))

        if not bars:
            continue

        # Target side positions (0-indexed from the cell adjacent to the line)
        if source_left:
            num_target = w - line_col - 1
            def target_col(p):
                return line_col + 1 + p
        else:
            num_target = line_col
            def target_col(p):
                return line_col - 1 - p

        for p in range(num_target):
            best_bar = None  # (dist, colour)
            for dist, color, length in bars:
                if p % length == 0:
                    if best_bar is None or dist < best_bar[0]:
                        best_bar = (dist, color)
            if best_bar is not None:
                out[r][target_col(p)] = best_bar[1]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find corner with 0
    corners = []
    if g[0, 0] == 0:
        corners.append('TL')
    if g[0, W - 1] == 0:
        corners.append('TR')
    if g[H - 1, 0] == 0:
        corners.append('BL')
    if g[H - 1, W - 1] == 0:
        corners.append('BR')

    if not corners:
        return [[int(x) for x in row] for row in g]

    corner = corners[0]

    # Remove frame edges
    if corner in ('TL', 'TR'):
        inner = g[1:, :]
    else:
        inner = g[:-1, :]
    if corner in ('TL', 'BL'):
        inner = inner[:, 1:]
    else:
        inner = inner[:, :-1]

    h, w = inner.shape
    seen = np.zeros((h, w), dtype=bool)
    blocks = []

    for i in range(h):
        for j in range(w):
            if seen[i, j] or inner[i, j] == 8:
                continue
            # 8-connected flood fill
            from collections import deque
            q = deque([(i, j)])
            seen[i, j] = True
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w:
                            if not seen[nx, ny] and inner[nx, ny] != 8:
                                seen[nx, ny] = True
                                q.append((nx, ny))

            ys = [x for x, _ in cells]
            xs = [y for _, y in cells]
            y_min, y_max = min(ys), max(ys)
            x_min, x_max = min(xs), max(xs)
            block = inner[y_min:y_max + 1, x_min:x_max + 1].copy()
            blocks.append((y_min, x_min, block))

    # Sort based on corner
    if corner == 'TL':
        blocks.sort(key=lambda b: (b[0], b[1]))
    elif corner == 'TR':
        blocks.sort(key=lambda b: (b[0], -b[1]))
    elif corner == 'BL':
        blocks.sort(key=lambda b: (-b[0], b[1]))
    else:  # BR
        blocks.sort(key=lambda b: (-b[0], -b[1]))

    if not blocks:
        return [[0]]

    max_w = max(bl.shape[1] for _, _, bl in blocks)
    n_blocks = len(blocks)
    out = np.full((n_blocks * 2, max_w), 8, dtype=int)

    for idx, (_, _, block) in enumerate(blocks):
        bh, bw = block.shape
        # Use first 2 rows of block (or pad with 8 if shorter)
        band = np.full((2, bw), 8, dtype=int)
        rows_to_use = min(2, bh)
        band[:rows_to_use, :] = block[:rows_to_use, :]
        x_off = (max_w - bw) // 2
        y_off = idx * 2
        out[y_off:y_off + 2, x_off:x_off + bw] = band

    return [[int(v) for v in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter, defaultdict

    g = np.array(grid, dtype=int)
    H, W = g.shape
    ans = g.copy()

    def is_ring(mask, r, c, h, w):
        if h < 3 or w < 3:
            return False
        if not mask[r, c] or not mask[r + h - 1, c + w - 1]:
            return False
        for x in range(w):
            if not mask[r, c + x] or not mask[r + h - 1, c + x]:
                return False
        for y in range(h):
            if not mask[r + y, c] or not mask[r + y, c + w - 1]:
                return False
        return True

    # Find rectangular ring frames (connected components whose occupied cells
    # exactly form the border of their bounding box).
    visited = np.zeros((H, W), dtype=bool)
    frames = []
    for r in range(H):
        for c in range(W):
            if visited[r, c] or g[r, c] == 0:
                continue
            col = int(g[r, c])
            q = [(r, c)]
            visited[r, c] = True
            cells = []
            min_r = max_r = r
            min_c = max_c = c
            while q:
                y, x = q.pop()
                cells.append((y, x))
                if y < min_r: min_r = y
                if y > max_r: max_r = y
                if x < min_c: min_c = x
                if x > max_c: max_c = x
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not visited[ny, nx] and int(g[ny, nx]) == col:
                                visited[ny, nx] = True
                                q.append((ny, nx))
            h = max_r - min_r + 1
            w = max_c - min_c + 1
            mask = np.zeros((H, W), dtype=bool)
            for y, x in cells:
                mask[y, x] = True
            if len(cells) == 2 * (h + w) - 4 and is_ring(mask, min_r, min_c, h, w):
                frames.append((min_r, min_c, h, w, col))

    # Process each frame independently.
    for r0, c0, fh, fw, frame_color in frames:
        if fh <= 2 or fw <= 2:
            continue
        ir = r0 + 1
        ic = c0 + 1
        ih = fh - 2
        iw = fw - 2
        if ih <= 0 or iw <= 0:
            continue

        sub = g[ir:ir + ih, ic:ic + iw]
        best = None

        # Try candidate periods.  The hidden patterns here are small, and the
        # interior is small too, so exhaustive search is safe.
        for px in range(1, iw + 1):
            for py in range(1, ih + 1):
                classes = defaultdict(list)
                for y in range(ih):
                    for x in range(iw):
                        classes[(x % px, y % py)].append((y, x))

                fill = np.zeros((ih, iw), dtype=int)
                score = 0
                tie = 0
                for key, coords in classes.items():
                    cnt = Counter(int(sub[y, x]) for y, x in coords)
                    best_color, best_count = cnt.most_common(1)[0]
                    # If tied, prefer the frame colour?  It is not needed for
                    # the given puzzles, but makes the choice deterministic.
                    if best_count < len(coords) / 2:
                        tie += 1
                    for y, x in coords:
                        fill[y, x] = best_color
                        if int(sub[y, x]) == best_color:
                            score += 1

                # Primary: minimal number of changed cells.
                # Secondary: smaller period; tertiary: less ambiguity.
                cand = (-score, px * py, tie, px, py)
                if best is None or cand < best[0]:
                    best = (cand, fill.copy())

        if best is not None:
            ans[ir:ir + ih, ic:ic + iw] = best[1]

    return ans.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Extend horizontal arithmetic progressions in each row.
    # For a set of columns sharing one colour in a row:
    #   if the smallest spacing is 1, fill the continuous run from the
    #   leftmost point to the rightmost point with that colour;
    #   otherwise fill the arithmetic progression with that spacing to the
    #   right edge.
    for r in range(H):
        cols = np.flatnonzero(g[r] != 0)
        if len(cols) == 0:
            continue

        # If all non-background cells in the row are the same colour and form
        # an arithmetic progression, use the explicit progression rule.
        colors = g[r, cols]
        if len(cols) >= 2 and np.all(colors == colors[0]):
            d = int(cols[1] - cols[0])
            ok = all(int(cols[i + 1] - cols[i]) == d for i in range(len(cols) - 1))
            if ok:
                if d == 1:
                    for c in range(int(cols[0]), int(cols[-1]) + 1):
                        out[r, c] = int(colors[0])
                else:
                    c = int(cols[0])
                    while c < W:
                        out[r, c] = int(colors[0])
                        c += d
                continue

        # Mixed-colour rows: the rightmost colour dominates.
        right_c = int(cols[-1])
        right_color = int(g[r, right_c])
        out[r, right_c] = right_color

        for c in cols:
            c = int(c)
            if c < right_c:
                out[r, c] = right_color

        # If there is an adjacent pair to the left, fill continuously to the
        # rightmost column.
        for i in range(len(cols) - 1):
            if int(cols[i + 1] - cols[i]) == 1:
                left = int(cols[i])
                for c in range(left, right_c + 1):
                    out[r, c] = right_color

    # Extend vertical arithmetic progressions in each column.
    # Same rule, but progression extends upward.
    for c in range(W):
        rows = np.flatnonzero(g[:, c] != 0)
        if len(rows) == 0:
            continue

        colors = g[rows, c]
        if len(rows) >= 2 and np.all(colors == colors[0]):
            d = int(rows[1] - rows[0])
            ok = all(int(rows[i + 1] - rows[i]) == d for i in range(len(rows) - 1))
            if ok:
                if d == 1:
                    for r in range(int(rows[0]), int(rows[-1]) + 1):
                        out[r, c] = int(colors[0])
                else:
                    r = int(rows[0])
                    while r >= 0:
                        out[r, c] = int(colors[0])
                        r -= d
                continue

        top_r = int(rows[0])
        top_color = int(g[top_r, c])
        out[top_r, c] = top_color

        for r in rows:
            r = int(r)
            if r > top_r:
                out[r, c] = top_color

        # If there is an adjacent vertical pair below the top, fill
        # continuously upward to the topmost row.
        for i in range(len(rows) - 1):
            if int(rows[i + 1] - rows[i]) == 1:
                bottom = int(rows[i + 1])
                for r in range(top_r, bottom + 1):
                    out[r, c] = top_color

    return out.tolist()

import numpy as np

def _step(points, direction):
    """
    points: sorted list of integer coordinates on one line, in reading order
            for rows (left to right) or bottom-to-top for columns.
    direction: 1 to extend toward larger coordinate, -1 to extend toward smaller.
    Return the smallest positive arithmetic step supported by points.
    """
    pts = list(points)
    n = len(pts)
    if n == 1:
        return 1

    candidates = []

    # Consecutive gaps.
    for i in range(n - 1):
        candidates.append(pts[i + 1] - pts[i])

    # Gaps between first point and every other point.
    for i in range(1, n):
        candidates.append(pts[i] - pts[0])

    # Gaps between last point and every earlier point.
    for i in range(n - 1):
        candidates.append(pts[-1] - pts[i])

    candidates = [d for d in candidates if d > 0]
    if not candidates:
        return 1

    best = None
    for d in sorted(set(candidates)):
        matches = 0
        for x in pts:
            if all(0 <= (x + k * d) < 100000 for k in range(0, 0)):
                pass
            # Count points lying on the infinite progression generated by any point with step d.
            # For this small setting, it is enough to check all pairs.
            pairs = sum(
                1 for a in pts for b in pts
                if a != b and ((b - a) % d == 0)
            )
            if pairs > matches:
                matches = pairs
                best = d

    if best is None:
        best = min(candidates)

    # Prefer steps that keep the filled progression compact.
    if direction == 1:
        span = max(pts) - min(pts)
    else:
        span = max(pts) - min(pts)
    possible = [d for d in sorted(set(candidates)) if d <= max(span, 1) + 1]
    if possible:
        # Choose the smallest step that explains at least two points.
        for d in possible:
            if any((b - a) % d == 0 and abs(b - a) > 0 for a in pts for b in pts):
                return d
    return best

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros((H, W), dtype=int)

    # Horizontal lines: leftmost point starts the progression, extend right.
    for r in range(H):
        cols = [c for c in range(W) if g[r, c] != 0]
        if not cols:
            continue

        left_c = cols[0]
        right_c = cols[-1]

        # Source colour: colour at the leftmost non-background cell.
        src_color = int(g[r, left_c])
        # If the rightmost cell has a different colour, it can capture the line.
        final_color = int(g[r, right_c]) if int(g[r, right_c]) != src_color else src_color

        # Use all cells of the source colour if they occur at least twice;
        # otherwise use the leftmost cell as a singleton pattern.
        src_cols = [c for c in cols if int(g[r, c]) == src_color]
        if len(src_cols) < 2:
            step = 1
        else:
            step = _step(src_cols, 1)

        # Fill the arithmetic progression starting at left_c to the right.
        # If there is a different rightmost capture colour, stop just before it,
        # but still paint the capture cell itself.
        c = left_c
        while c < W:
            if c == right_c and int(g[r, c]) != src_color:
                out[r, c] = int(g[r, c])
                break
            out[r, c] = final_color
            c += step

        # If the capture cell was not on the progression and the line is
        # horizontal, the examples show it captures immediately to the left
        # of the last generated point.  Paint that adjacent cell too.
        if int(g[r, right_c]) != src_color:
            last = left_c
            while last + step < right_c:
                last += step
            if last + 1 == right_c:
                out[r, last + 1] = final_color
            elif last + 1 < right_c:
                # Adjacent capture at the right end.
                out[r, right_c - 1] = final_color

        # Preserve original non-background cells that were not painted,
        # unless they are the capture cell or already painted consistently.
        for c in cols:
            if out[r, c] == 0:
                out[r, c] = g[r, c]

    # Vertical lines: bottommost point starts the progression, extend upward.
    for c in range(W):
        rows = [r for r in range(H) if g[r, c] != 0]
        if not rows:
            continue

        # Work bottom-to-top: bottom coordinate is H-1-r, top is H-1.
        # Convert to bottom-origin coordinates: b = H - 1 - r.
        bpts = [H - 1 - r for r in rows]
        bottom_b = max(bpts)       # corresponds to largest row index (bottom)
        top_b = min(bpts)          # corresponds to smallest row index (top)

        bottom_r = H - 1 - bottom_b
        top_r = H - 1 - top_b

        src_color = int(g[bottom_r, c])
        final_color = int(g[top_r, c]) if int(g[top_r, c]) != src_color else src_color

        src_rows = [H - 1 - b for b in bpts if int(g[H - 1 - b, c]) == src_color]
        if len(src_rows) < 2:
            step = 1
        else:
            src_bpts = [H - 1 - r for r in src_rows]
            step = _step(sorted(src_bpts, reverse=True), -1)

        b = bottom_b
        while b >= 0:
            r = H - 1 - b
            if b == top_b and int(g[r, c]) != src_color:
                out[r, c] = int(g[r, c])
                break
            out[r, c] = final_color
            b -= step

        # Preserve original non-background cells not already painted.
        for r in rows:
            if out[r, c] == 0:
                out[r, c] = g[r, c]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)
    color_cells = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0:
                color_cells[g[r, c]].append((r, c))

    def connected_components(cells):
        cells = set(cells)
        comps = []
        while cells:
            start = next(iter(cells))
            stack = [start]
            cells.remove(start)
            comp = [start]
            while stack:
                r, c = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nb = (r + dr, c + dc)
                        if nb in cells:
                            cells.remove(nb)
                            stack.append(nb)
                            comp.append(nb)
            comps.append(comp)
        return comps

    objects = []
    for color, cells in color_cells.items():
        for comp in connected_components(cells):
            rows = [r for r, c in comp]
            cols = [c for r, c in comp]
            objects.append({
                "color": color,
                "cells": set(comp),
                "min_r": min(rows),
                "max_r": max(rows),
                "min_c": min(cols),
                "max_c": max(cols),
                "size": len(comp),
            })

    for ob in objects:
        ob["centroid_r"] = sum(r for r, c in ob["cells"]) / ob["size"]
        ob["centroid_c"] = sum(c for r, c in ob["cells"]) / ob["size"]

    def contains_bbox(a, b, margin=1):
        return (a["min_r"] - margin <= b["min_r"] and
                a["max_r"] + margin >= b["max_r"] and
                a["min_c"] - margin <= b["min_c"] and
                a["max_c"] + margin >= b["max_c"])

    groups = []
    used_sats = set()

    for cont in objects:
        if cont["color"] == 0:
            continue
        for sat in objects:
            if sat is cont or sat["color"] == cont["color"]:
                continue
            if len(sat) < cont["size"]:
                continue
            if contains_bbox(cont, sat):
                key = (id(cont), sat["color"])
                if key in used_sats:
                    continue
                used_sats.add(key)
                groups.append((cont, sat))

    if groups:
        for r, c in range(h) if False else range(h):
            pass

    for cont, sat in groups:
        cr1, cr2 = cont["min_r"], cont["max_r"]
        cc1, cc2 = cont["min_c"], cont["max_c"]
        sr1, sr2 = sat["min_r"], sat["max_r"]
        sc1, sc2 = sat["min_c"], sat["max_c"]

        dist = {
            "up": cont["centroid_r"] - sr1,
            "down": sr2 - cont["centroid_r"],
            "left": cont["centroid_c"] - sc1,
            "right": sc2 - cont["centroid_c"],
        }
        side = max(dist, key=lambda k: (dist[k], k in ("up", "left")))

        if side == "up":
            length = sr2 - sr1 + 1
            anchor_c = int(round(cont["centroid_c"]))
            cells = [(cr1 - i, anchor_c) for i in range(length)]
        elif side == "down":
            length = sr2 - sr1 + 1
            anchor_c = int(round(cont["centroid_c"]))
            cells = [(cr2 + i + 1, anchor_c) for i in range(length)]
        elif side == "left":
            length = sc2 - sc1 + 1
            anchor_r = int(round(cont["centroid_r"]))
            cells = [(anchor_r, cc1 - i - 1) for i in range(length)]
        else:
            length = sc2 - sc1 + 1
            anchor_r = int(round(cont["centroid_r"]))
            cells = [(anchor_r, cc2 + i + 1) for i in range(length)]

        for r, c in cells:
            if 0 <= r < h and 0 <= c < w:
                out[r, c] = sat["color"]

    for ob in objects:
        if any(ob is sat for _, sat in groups):
            continue
        for r, c in ob["cells"]:
            out[r, c] = ob["color"]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = np.zeros((h, w), dtype=int)

    # Collect connected 8-components by colour.
    visited = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != 0 and not visited[r, c]:
                col = a[r, c]
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not visited[ny, nx] and a[ny, nx] == col:
                                    visited[ny, nx] = True
                                    stack.append((ny, nx))
                comps.append({"color": col, "cells": set(cells)})

    for cp in comps:
        rs = [r for r, c in cp["cells"]]
        cs = [c for r, c in cp["cells"]]
        cp["min_r"] = min(rs)
        cp["max_r"] = max(rs)
        cp["min_c"] = min(cs)
        cp["max_c"] = max(cs)
        cp["size"] = len(cp["cells"])
        cp["height"] = cp["max_r"] - cp["min_r"] + 1
        cp["width"] = cp["max_c"] - cp["min_c"] + 1
        cp["cr"] = sum(rs) / cp["size"]
        cp["cc"] = sum(cs) / cp["size"]

    def contains(outer, inner):
        return (outer["min_r"] <= inner["min_r"] and
                outer["max_r"] >= inner["max_r"] and
                outer["min_c"] <= inner["min_c"] and
                outer["max_c"] >= inner["max_c"])

    # Pair each small component with a strictly larger component that contains it.
    pairs = []
    used = set()
    for inner in comps:
        for outer in comps:
            if outer is inner or inner["color"] == outer["color"]:
                continue
            if inner["size"] < outer["size"] and contains(outer, inner):
                key = (id(inner), id(outer))
                if key not in used:
                    used.add(key)
                    pairs.append((outer, inner))

    # If there are several payload components inside the same container,
    # merge their bounding boxes before placing the output segment.
    by_outer = defaultdict(list)
    for outer, inner in pairs:
        by_outer[id(outer)].append(inner)

    for outer_id, inners in by_outer.items():
        outer = next(c for c in comps if id(c) == outer_id)
        min_r = min(x["min_r"] for x in inners)
        max_r = max(x["max_r"] for x in inners)
        min_c = min(x["min_c"] for x in inners)
        max_c = max(x["max_c"] for x in inners)
        color = inners[0]["color"]

        # Side occupancy on the four sides of the outer object's bounding box.
        occ = {
            "up": sum(1 for r, c in outer["cells"] if r == outer["min_r"]),
            "down": sum(1 for r, c in outer["cells"] if r == outer["max_r"]),
            "left": sum(1 for r, c in outer["cells"] if c == outer["min_c"]),
            "right": sum(1 for r, c in outer["cells"] if c == outer["max_c"]),
        }

        best = None
        # Natural ARC-style priority: prefer the least “closed” side,
        # with fixed side order up, left, right, down.
        for side in ("up", "left", "right", "down"):
            val = occ[side]
            if best is None or val < best[0]:
                best = (val, side)

        side = best[1]

        if side == "up":
            anchor_r = outer["min_r"] - 1
            anchor_c = next(c for r, c in outer["cells"] if r == outer["min_r"])
            length = max_r - min_r + 1
            for i in range(length):
                r = anchor_r - i
                c = anchor_c
                if 0 <= r < h and 0 <= c < w:
                    out[r, c] = color
        elif side == "down":
            anchor_r = outer["max_r"] + 1
            anchor_c = next(c for r, c in outer["cells"] if r == outer["max_r"])
            length = max_r - min_r + 1
            for i in range(length):
                r = anchor_r + i
                c = anchor_c
                if 0 <= r < h and 0 <= c < w:
                    out[r, c] = color
        elif side == "left":
            anchor_r = next(r for r, c in outer["cells"] if c == outer["min_c"])
            anchor_c = outer["min_c"] - 1
            length = max_c - min_c + 1
            for i in range(length):
                r = anchor_r
                c = anchor_c - i
                if 0 <= r < h and 0 <= c < w:
                    out[r, c] = color
        else:  # right
            anchor_r = next(r for r, c in outer["cells"] if c == outer["max_c"])
            anchor_c = outer["max_c"] + 1
            length = max_c - min_c + 1
            for i in range(length):
                r = anchor_r
                c = anchor_c + i
                if 0 <= r < h and 0 <= c < w:
                    out[r, c] = color

        # Remove the payload cells.
        for inner in inners:
            for r, c in inner["cells"]:
                out[r, c] = 0

    # Keep all components that were not removed as payloads.
    moved_ids = {id(inner) for inners in by_outer.values() for inner in inners}
    for cp in comps:
        if id(cp) in moved_ids:
            continue
        for r, c in cp["cells"]:
            out[r, c] = cp["color"]

    return out.tolist()

