    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    comps = []
    used = np.zeros((H, W), dtype=bool)

    for col in sorted(colors):
        for r0, c0 in cells_of_color(col):
            if used[r0, c0]:
                continue
            stack = [(r0, c0)]
            used[r0, c0] = True
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for nr, nc in neighbors8(r, c):
                    if not used[nr, nc] and grid[nr][nc] == col:
                        used[nr, nc] = True
                        stack.append((nr, nc))
            comps.append((col, cells))

    by_color = {}
    for col, cells in comps:
        by_color.setdefault(col, []).append(cells)

    out = [list(row) for row in grid]

    def paint(r, c, col):
        if 0 <= r < H and 0 <= c < W and out[r][c] == 0:
            out[r][c] = col

    for col, objs in by_color.items():
        for cells in objs:
            if len(cells) == 3:
                rs = [r for r, _ in cells]
                cs = [c for _, c in cells]

                if len(set(rs)) == 1:
                    c0 = min(cs)
                    c1 = max(cs)
                    mid_c = (c0 + c1) // 2
                    for k in range(1, max(H, W) + 1):
                        r = rs[0] - k
                        c = mid_c + k
                        if r < 0:
                            break
                        paint(r, c, col)
                        r = rs[0] + k
                        c = mid_c + k
                        if r >= H:
                            break
                        paint(r, c, col)

                elif len(set(cs)) == 1:
                    r0 = min(rs)
                    r1 = max(rs)
                    mid_r = (r0 + r1) // 2
                    for k in range(1, max(H, W) + 1):
                        r = mid_r + k
                        c = cs[0] - k
                        if c < 0:
                            break
                        paint(r, c, col)
                        r = mid_r - k
                        c = cs[0] + k
                        if r < 0:
                            break
                        paint(r, c, col)

                else:
                    rs_set = set(rs)
                    cs_set = set(cs)
                    if len(rs_set) == 2 and len(cs_set) == 2:
                        a = (min(rs), min(cs))
                        b = (min(rs), max(cs))
                        c = (max(rs), min(cs))
                        d = (max(rs), max(cs))
                        present = set(cells)
                        for p in (a, b, c, d):
                            if p not in present:
                                missing = p
                                break
                        start = (d if d in present else
                                 c if c in present else
                                 b if b in present else a)
                        for k in range(1, max(H, W) + 1):
                            r = start[0] + k
                            c = start[1] + k
                            if r >= H or c >= W:
                                break
                            paint(r, c, col)
                    else:
                        for dr, dc in ((1, 1), (1, -1)):
                            start = min(cells, key=lambda p: p[0] * -dr + p[1] * -dc)
                            for k in range(1, max(H, W) + 1):
