def transform(grid: list[list[int]]) -> list[list[int]]:
    """
    Rule:
    - There is a vertical wall of 5s.
    - Every 8-connected component of 0s on the left of the wall is shifted
      right until its rightmost cell is immediately left of the wall.
    - A row gets colour 2 on the right side of the wall if, after shifting,
      that row has a 0 immediately left of the wall and a background 6
      immediately to the left of that 0 (a right-edge notch/hole).
    """
    if not grid:
        return []

    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [[int(c) for c in row] for row in grid]

    # Find the vertical wall of 5s.
    wall_cols = [c for c in range(W) if all(grid[r][c] == 5 for r in range(H))]
    if wall_cols:
        wall = min(wall_cols)
    else:
        # Fallback: column with the most 5s.
        from collections import Counter
        cnt = Counter()
        for c in range(W):
            if any(grid[r][c] == 5 for r in range(H)):
                cnt[c] = sum(1 for r in range(H) if grid[r][c] == 5)
        if not cnt:
            return out
        wall = max(cnt.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    left_limit = wall - 1
    if left_limit < 0:
        # Nothing to move; ensure plain ints.
        return [[int(v) for v in row] for row in out]

    # Extract 8-connected 0 components from the input.
    seen = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not seen[ny][nx] and grid[ny][nx] == 0:
                                    seen[ny][nx] = True
                                    stack.append((ny, nx))
                components.append(cells)

    # Clear all original 0 cells to the left of the wall.
    for r in range(H):
        for c in range(0, left_limit + 1):
            if out[r][c] == 0:
                out[r][c] = 6

    # Shift each component right until its rightmost cell is at left_limit.
    for cells in components:
        if not cells:
            continue

        # Only process components that are originally left of the wall.
        if min(x for _, x in cells) > left_limit:
            continue

        max_c = max(x for _, x in cells)
        shift = left_limit - max_c

        # If the component already crosses or touches the wall, do not move it.
        if shift < 0:
            shift = 0

        for y, x in cells:
            nx = x + shift
            if 0 <= y < H and 0 <= nx <= left_limit:
                out[y][nx] = 0

    # Paint 2s to the right of the wall in rows with the notch condition.
    for r in range(H):
        if out[r][left_limit] == 0 and out[r][left_limit - 1] == 6:
            for c in range(wall + 1, W):
                out[r][c] = 2

    # Keep the wall as 5 and return plain ints.
    for r in range(H):
        out[r][wall] = 5
        out[r] = [int(v) for v in out[r]]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    if not grid:
        return out

    h = len(grid)
    w = len(grid[0])

    # Collect all non-background pixels, grouped by anti-diagonal r + c.
    diag = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8:
                diag.setdefault(r + c, []).append((r, c))

    # A valid marker diagonal must contain at least two cells
    # and those cells must all lie on the same r + c line.
    valid = {}
    for s, pts in diag.items():
        if len(pts) < 2:
            continue
        r0, c0 = pts[0]
        if all(r + c == s for r, c in pts):
            valid[s] = pts

    if not valid:
        return out

    s_vals = sorted(valid)

    # Fill interiors between consecutive marker diagonals.
    # In (u = r + c, v = r - c) coordinates, marker diagonals are
    # vertical segments at u = s.  The filled area between two such
    # segments is the intersection of the triangle/parallelogram
    # swept between their endpoint v-ranges.
    for i in range(len(s_vals) - 1):
        s1 = s_vals[i]
        s2 = s_vals[i + 1]

        # Inclusive endpoint ranges in v-coordinate.
        v1a, v1b = min(r - c for r, c in valid[s1]), max(r - c for r, c in valid[s1])
        v2a, v2b = min(r - c for r, c in valid[s2]), max(r - c for r, c in valid[s2])

        if v1a > v1b:
            v1a, v1b = v1b, v1a
        if v2a > v2b:
            v2a, v2b = v2b, v2a

        # Fill only the open strip between the two marker diagonals.
        for s in range(s1 + 1, s2):
            # Interpolate the two possible boundary edges.
            # Edge from low endpoint to low endpoint:
            v_edge_low = v1a + (v2a - v1a) * (s - s1) / (s2 - s1)
            # Edge from high endpoint to high endpoint:
            v_edge_high = v1b + (v2b - v1b) * (s - s1) / (s2 - s1)

            # Keep the interior of the quadrilateral in (u, v)-space.
            v_min = min(v_edge_low, v_edge_high)
            v_max = max(v_edge_low, v_edge_high)

            # Add a tiny epsilon so exact boundary pixels (which are
            # marker cells or other non-background cells) are not overwritten.
            eps = 1e-7
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == 8 and r + c == s:
                        v = r - c
                        if v_min + eps < v < v_max - eps:
                            out[r][c] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    out = [row[:] for row in grid]

    # Precompute, for every cell, whether there is a non-background cell
    # in each of the four diagonal directions (excluding the cell itself).
    # up_right: (r - k, c + k)
    # down_left: (r + k, c - k)
    # up_left: (r - k, c - k)
    # down_right: (r + k, c + k)
    up_right = [[False] * w for _ in range(h)]
    down_left = [[False] * w for _ in range(h)]
    up_left = [[False] * w for _ in range(h)]
    down_right = [[False] * w for _ in range(h)]

    def is_marker(r, c):
        return 0 <= r < h and 0 <= c < w and grid[r][c] != 8

    for r in range(h):
        # up_right / down_left use same r-c diagonal
        for c in range(w):
            if grid[r][c] != 8:
                # mark cells that have this marker up-right
                rr, cc = r, c
                while rr + 1 < h and cc - 1 >= 0:
                    rr += 1
                    cc -= 1
                    up_right[rr][cc] = True
                # mark cells that have this marker down-left
                rr, cc = r, c
                while rr - 1 >= 0 and cc + 1 < w:
                    rr -= 1
                    cc += 1
                    down_left[rr][cc] = True

    for r in range(h):
        # up_left / down_right use same r+c diagonal
        for c in range(w):
            if grid[r][c] != 8:
                # mark cells that have this marker up-left
                rr, cc = r, c
                while rr + 1 < h and cc + 1 < w:
                    rr += 1
                    cc += 1
                    up_left[rr][cc] = True
                # mark cells that have this marker down-right
                rr, cc = r, c
                while rr - 1 >= 0 and cc - 1 >= 0:
                    rr -= 1
                    cc -= 1
                    down_right[rr][cc] = True

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8:
                continue

            paint = False
            if up_right[r][c] and down_left[r][c]:
                paint = True
            elif down_left[r][c] and up_right[r][c]:
                paint = True
            elif up_left[r][c] and down_right[r][c]:
                paint = True
            elif down_right[r][c] and up_left[r][c]:
                paint = True

            if paint:
                out[r][c] = 2

    return out

