def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Identify the most common colour as background.
    vals, counts = np.unique(a, return_counts=True)
    bg = vals[np.argmax(counts)]

    # The two colours that will be recoloured are the only non-background
    # colours that appear as 8-connected components of size exactly 2.
    nonbg = [v for v in vals if v != bg]
    active = []
    for c in nonbg:
        mask = (a == c)
        seen = np.zeros_like(mask, dtype=bool)
        for i in range(h):
            for j in range(w):
                if mask[i, j] and not seen[i, j]:
                    stack = [(i, j)]
                    seen[i, j] = True
                    size = 0
                    while stack:
                        y, x = stack.pop()
                        size += 1
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < h and 0 <= nx < w:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        stack.append((ny, nx))
                    if size == 2:
                        active.append(c)
                        break
                elif mask[i, j] and not seen[i, j]:
                    # small guard; component sizes here are tiny
                    pass

    if len(active) < 2:
        return a.tolist()

    # Assign colours by relative spatial position.
    # Leftmost recolourable object becomes 3, the other becomes 5.
    # If tied in x-coordinate, the lower one becomes 3 (matches all examples).
    def centroid(c):
        ys, xs = np.where(a == c)
        return (xs.mean(), ys.mean())

    c3, c5 = sorted(active, key=lambda c: (centroid(c)[0], centroid(c)[1]))

    out = a.copy()
    # Recolour only size-2 objects of these two colours.
    for c in (c3, c5):
        newc = 3 if c == c3 else 5
        mask = (a == c)
        seen = np.zeros_like(mask, dtype=bool)
        for i in range(h):
            for j in range(w):
                if mask[i, j] and not seen[i, j]:
                    stack = [(i, j)]
                    seen[i, j] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < h and 0 <= nx < w:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        stack.append((ny, nx))
                    if len(cells) == 2:
                        for y, x in cells:
                            out[y, x] = newc

    return out.tolist()

