from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = a.copy()

    # connected components of colour 1, 8-connected
    mask = (a == 1)
    seen = np.zeros_like(mask, dtype=bool)
    comps = []
    for i in range(H):
        for j in range(W):
            if mask[i, j] and not seen[i, j]:
                q = deque([(i, j)])
                seen[i, j] = True
                cells = []
                while q:
                    r, c = q.popleft()
                    cells.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < H and 0 <= nc < W and mask[nr, nc] and not seen[nr, nc]:
                                seen[nr, nc] = True
                                q.append((nr, nc))
                comps.append(cells)

    # mark all input-1 cells belonging to components that enclose a background hole
    fill8 = np.zeros((H, W), dtype=bool)

    for comp in comps:
        rs = [r for r, _ in comp]
        cs = [c for _, c in comp]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)

        # background cells inside bbox that are enclosed by the component
        # flood from bbox border through non-1 cells; what remains is enclosed.
        internal = np.zeros((H, W), dtype=bool)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if a[r, c] != 1:
                    internal[r, c] = True

        for r in range(r0, r1 + 1):
            for c in (c0, c1):
                if internal[r, c]:
                    q = deque([(r, c)])
                    internal[r, c] = False
                    while q:
                        rr, cc = q.popleft()
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == dc == 0:
                                    continue
                                nr, nc = rr + dr, cc + dc
                                if r0 <= nr <= r1 and c0 <= nc <= c1 and internal[nr, nc]:
                                    internal[nr, nc] = False
                                    q.append((nr, nc))
        for c in range(c0, c1 + 1):
            for r in (r0, r1):
                if internal[r, c]:
                    q = deque([(r, c)])
                    internal[r, c] = False
                    while q:
                        rr, cc = q.popleft()
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == dc == 0:
                                    continue
                                nr, nc = rr + dr, cc + dc
                                if r0 <= nr <= r1 and c0 <= nc <= c1 and internal[nr, nc]:
                                    internal[nr, nc] = False
                                    q.append((nr, nc))

